[4512] = {id=4512,name="A Little Slime Goes a Long Way",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=1537,description="But the thing I've studied most is ooze. I know it sounds odd, but they're all over! I helped a lady in Menethil find her bag not too long ago--it was eaten by oozes. I've seen members of the Royal Apothecary Society from Undercity collecting samples of the stuff. I want to know why! Where does it come from? I've heard of more in Felwood. What I need are samples of the oozes there so I can further my research. I'll give you containers, you use them to collect a sample from the deceased creatures.",starts={{npcID=9616,x=0.754,y=0.234,zoneID=1537}},ends={{npcID=9616,x=0.754,y=0.234,zoneID=1537}},coords={x=0.754,y=0.234,source="quest_giver",zoneID=1537},questType="standard"},
[4513] = {id=4513,name="A Little Slime Goes a Long Way",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=1537,description="I'm going to need more samples, . But--and I don't know how to put this--they have to be pure samples. I know, I know. \"What does 'pure' mean, Laris?\" I'm not sure. I do know that these are corrupt... just like Felwood. Which is what makes my realization so important. The oozes seem to adapt... to take on the aspects of the area they're in. I'll need to find samples that haven't been polluted. But where? Where?! Bah! , take these containers just in case you find any on your own.",starts={{npcID=9616,x=0.754,y=0.234,zoneID=1537}},ends={{npcID=9616,x=0.754,y=0.234,zoneID=1537}},coords={x=0.754,y=0.234,source="quest_giver",zoneID=1537},questType="standard"},
[4601] = {id=4601,name="The Sparklematic 5200!",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=5495,description="This contraption stands out amongst the gnomes holding out against the madness outside the room. A small plaque on the device reads \" The Sparklematic 5200 \", followed by some text: \"Grime and residue ruining your sparklies? The Sparklematic 5200 puts the shine back in shine-tastic! Insert the item you wish to clean and deposit three silver coins in the coin slot. Give The Sparklematic 5200 a moment for operation, and voila! Your valuables will emerge clean and shiny!\"",questType="dungeon"},
