[4621] = {id=4621,name="Avast Ye, Admiral!",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=5287,description="Listen close, sea dawg... the powers of Booty Bay is what keeps us Bloodsail from sailing wheres we like and taking whats we want as rights o' plunder. Were ye to put a knife to Fleet Master Seahorn , we'd ne'er run afoul of a Booty Bay 's vessel. Were ye to put a knife to Baron Revilgaz , we'd ne'er face the law on their terms. If ye are to be an honorary admiral amongst us - yes, ADMIRAL, you'll puts a knife to both of 'em as I've says. Go now , and return to me once ye does the deeds.",starts={{npcID=2546,x=0.466,y=0.952,zoneID=5287}},ends={{npcID=2546,x=0.466,y=0.952,zoneID=5287}},coords={x=0.466,y=0.952,source="quest_giver",zoneID=5287},questType="standard"},
[4785] = {id=4785,name="Fine Gold Thread",level=15,requiredLevel=15,faction="none",expansion=0,questType="standard"},
[5041] = {id=5041,name="Supplies for the Crossroads",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,description="Whatever has happened in Southern Barrens is causing some of the quilboar tribes to flee our direction. The displaced Razormane in particular grow desperate, and their attacks grow bolder. I've lost two caravans this week alone! Our warriors at the Crossroads desperately need those supplies, and I'm not about to let the quilboar grow fat off of their misdeeds. Find the missing supply crates and bring them to me. I'd search the quilboar hovel south of here, along the river.",starts={{npcID=34258,x=0.674,y=0.388,zoneID=17}},ends={{npcID=3429,x=0.486,y=0.596,zoneID=17},{npcID=34258,x=0.674,y=0.388,zoneID=17}},coords={x=0.674,y=0.388,source="quest_giver",zoneID=17},questType="standard"},
[5421] = {id=5421,name="Fish in a Bucket",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=405,description="I'll reward anyone who makes my life a bit easier... I enjoy doing as little as possible, mon! Below the docks here in Shadowprey Village, I've many shellfish traps. If you're kind enough to do my work and collect me my shellfish , then I'll reward you with something you want... get my drift mon?",starts={{npcID=11317,x=0.224,y=0.73,zoneID=405}},ends={{npcID=11317,x=0.224,y=0.73,zoneID=405}},coords={x=0.224,y=0.73,source="quest_giver",zoneID=405},questType="standard"},
[5501] = {id=5501,name="Bone Collector",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=405,description="We're sitting on a goldmine here, I tell you - a goldmine! Kodo bones will change the world forever... I have customers making furniture, music instruments, and even blasting powder out of them. There's a caravan that comes by and picks up my Kodo bones and then sells them at Shadowprey Village. If you can travel to the kodo graveyard south of here and bring me ten Kodo bones , I'll give you something in return. Is it a deal?",starts={{npcID=11438,x=0.622,y=0.388,zoneID=405}},ends={{npcID=11438,x=0.622,y=0.388,zoneID=405}},coords={x=0.622,y=0.388,source="quest_giver",zoneID=405},questType="standard"},
[5502] = {id=5502,name="A Warden of the Horde",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=6738,description="You have been so very kind to me, . I never dreamed that I'd have so much fun during Children's Week. Thank you. I wish all the orphans were lucky enough to get to see all the stuff we did. Do you think we find Blax Bottlerocket again and get a foam sword rack from him? I think he's still pushing that cart up and down the main road in the Drag. That way, everyone else at the orphanage could do something fun too! After that, it'll be time for me to go home.",ends={{npcID=14451,x=0.58,y=0.576,zoneID=1637},{npcID=51989,x=0.58,y=0.576,zoneID=1637}},questType="standard"},
[5545] = {id=5545,name="A Bundle of Trouble",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,description="I've got a real problem on my hands. I have a deadline looming for an order of lumber, and I'm running out of time. The wolves and bears north of here have chased my workers away from the bundles of wood that they've already chopped. I've already talked to Deputy Rainer about clearing the animals, but I need someone to go collect the wood for me. If you could collect eight bundles of wood for me I might just make my deadline.",starts={{npcID=10616,x=0.814,y=0.662,zoneID=12}},ends={{npcID=10616,x=0.814,y=0.662,zoneID=12}},coords={x=0.814,y=0.662,source="quest_giver",zoneID=12},questType="standard"},
[5561] = {id=5561,name="Kodo Roundup",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=405,description="Bibbly thinks he is the only goblin in Desolace who knows how to make money. Well, the only caravan brave enough to travel these parts relies on me. Ever since I learned how to rejuvenate and control aged kodos with my kodo kombobulator , the caravan owner Cork, Rigger, and I entered a partnership. Take the kombobulator and use it on any ancient or aged kodos; it will jolt the beast into a tamed kodo and force it to follow you. Once you have a kodo tamed, bring it back to me.",starts={{npcID=11596,x=0.608,y=0.618,zoneID=405}},ends={{npcID=11596,x=0.608,y=0.618,zoneID=405}},coords={x=0.608,y=0.618,source="quest_giver",zoneID=405},questType="standard"},
[5581] = {id=5581,name="Portals of the Legion",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=405,description="Here it is - the Hand of Iruxos . Got it from one of the Burning Blade leaders myself. You must possess it if the demon portals at Mannoroc Coven are to be banished... which is what I now ask you to do. With the demon threat increasing we must close these portals to stem the tide of demons to this world.",starts={{npcID=5395,x=0.562,y=0.594,zoneID=405}},ends={{npcID=5395,x=0.562,y=0.594,zoneID=405},{npcID=11624,x=0.258,y=0.682,zoneID=405}},coords={x=0.562,y=0.594,source="quest_giver",zoneID=405},questType="standard"},
[5713] = {id=5713,name="One Shot. One Kill.",level=5,requiredLevel=5,faction="alliance",expansion=0,zoneID=331,description="I was traveling to Lor'danel with an important message when I was attacked by the furbolg Marosh and his trackers. During the attack I was poisoned, leaving me barely able to stand. I can make an antidote, but it will take time before it is ready. I would ask that you defend me until I can apply the antidote. I will aid you with my bow as best I can. Should we survive, I will be able to deliver my message to Lor'danel, while you speak with Onaeya at Maestra's Post to inform her of this incident.",starts={{npcID=11711,x=0.476,y=0.888,zoneID=148}},ends={{npcID=11806,x=0.266,y=0.368,zoneID=331}},coords={x=0.476,y=0.888,source="quest_giver",zoneID=148},questType="standard"},
[5892] = {id=5892,name="Irondeep Supplies",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,description="Before the fighting started, we stored supplies for Dun Baldar in the Irondeep mine. The troggs that surfaced there weren't much of a problem when we had spare troops to guard the mine, but now that we're fighting with the Horde we can't maintain control of Irondeep. We need the supplies in Irondeep, . Enter the mine and bring me a load of them.",starts={{npcID=12096,zoneID=2597},{npcID=12096,zoneID=10458}},ends={{npcID=12096,zoneID=2597},{npcID=12096,zoneID=10458}},questType="pvp"},
[5893] = {id=5893,name="Coldtooth Supplies",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,description="The Coldtooth mine to the north was once an ideal place to store extra supplies, but now that the fighting with the Stormpikes grows fierce, we do not always have the spare warriors to station at the mine and protect it. And so, control of the mine often falls to the Alliance, or to underground denizens... But we still need our supplies, ! Go to the Coldtooth mine and bring me a load of them. And be wary of enemies as you go; the tides of battle shift quickly in that place...",starts={{npcID=12097,x=0.466,y=0.84,zoneID=2597},{npcID=12097,zoneID=10458}},ends={{npcID=12097,x=0.466,y=0.84,zoneID=2597},{npcID=12097,zoneID=10458}},coords={x=0.466,y=0.84,source="quest_giver",zoneID=2597},questType="pvp"},
[6031] = {id=6031,name="Runecloth",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=361,description="In Timbermaw, we are content. We do not like strangers. This is good for us, but it is bad for trade. Not long ago, a rare night elf friend came to Timbermaw and she wore a runecloth cloak. runecloth is rare among us, but the cloak was so fine my people want me to make more runecloth clothing. Will you bring me runecloth ? If you bring me enough, then I will give you something in trade.",starts={{npcID=11557,x=0.648,y=0.052,zoneID=361}},ends={{npcID=11557,x=0.648,y=0.052,zoneID=361}},coords={x=0.648,y=0.052,source="quest_giver",zoneID=361},questType="standard"},
[6032] = {id=6032,name="Sacred Cloth",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=361,description="Although the people of Timbermaw delight in the feel of runecloth, it is not sacred to us. But mooncloth is sacred. Bring me a small supply of this holy cloth, and I will teach you a secret fashioning technique.",starts={{npcID=11557,x=0.648,y=0.052,zoneID=361}},ends={{npcID=11557,x=0.648,y=0.052,zoneID=361}},coords={x=0.648,y=0.052,source="quest_giver",zoneID=361},questType="standard"},
[6132] = {id=6132,name="Get Me Out of Here!",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=405,description="Get me out of here! I came up to the Valley of Spears to talk to the Maraudines. I thought I could do a little business with them... but they don't want to talk! I think they want to eat me! Get me out of here and my brother Hornizz will pay you big! He's at our camp next to the kodo graveyard, to the east. Let's hurry, . Not two minutes ago I heard some centaurs talking about getting wood for their cookpot...",starts={{npcID=12277,x=0.338,y=0.534,zoneID=405}},ends={{npcID=6019,x=0.478,y=0.618,zoneID=405}},coords={x=0.338,y=0.534,source="quest_giver",zoneID=405},questType="standard"},
[6134] = {id=6134,name="Ghost-o-plasm Round Up",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=405,description="There's a valley to the southeast, the Valley of Bones, haunted by Magram ghosts. Sounds scary, doesn't it? Well think how scary it is to the Magram! If we captured ghost energy from that place, I bet it'd be worth plenty to those centaurs. Here, take this crate of ghost magnets . If you place one between the two big skeletons in the valley, the Dead Goliaths, then ghosts will wander to it. Distance yourself, take out the ghosts and get their ghost-o-plasm --that's what we'll sell to the Magram.",starts={{npcID=6019,x=0.478,y=0.618,zoneID=405}},ends={{npcID=6019,x=0.478,y=0.618,zoneID=405}},coords={x=0.478,y=0.618,source="quest_giver",zoneID=405},questType="standard"},
[6321] = {id=6321,name="Supplying Brill",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=85,description="Executor Zygand asked me to take stock of our equipment here in Brill. With the Scourge, and worse, lurking in the woods, he doesn't want the Deathguards to lack gear they might need. I found that we are, in general, well stocked, but we do need more weapons to replace those lost in the field. Here is a requisition order of what is needed, for the weapon dealer Gordon Wendham in the Undercity. Take the order to Bat Handler Anette and speak with her about transport to the Undercity.",starts={{npcID=1745,x=0.602,y=0.524,zoneID=85}},ends={{npcID=43124,x=0.588,y=0.518,zoneID=85}},coords={x=0.602,y=0.524,source="quest_giver",zoneID=85},questType="standard"},
[6322] = {id=6322,name="Michael Garrett",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1497,description="I have placed Brill's supplies into this crate. If you have already visited Brill and spoken with their bat master, then you may ride a bat back to her. Speak with the Undercity's bat master, Michael Garrett . He can provide you with a bat to Brill.",starts={{npcID=4556,x=0.618,y=0.42,zoneID=1497}},ends={{npcID=4551,x=0.63,y=0.482,zoneID=1497}},coords={x=0.618,y=0.42,source="quest_giver",zoneID=1497},questType="standard"},
[6323] = {id=6323,name="Ride to the Undercity",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1497,description="One of my bats can take you to the Undercity. Normally these flights require a small fee, but the flight to Undercity is complimentary for a like you. Speak with me again when you are ready so that we may arrange your transport. You will find Gordon Wendham in the Trade Quarter of the Undercity. That is the same quarter where my bat will land.",starts={{npcID=43124,x=0.588,y=0.518,zoneID=85}},ends={{npcID=4556,x=0.618,y=0.42,zoneID=1497}},coords={x=0.588,y=0.518,source="quest_giver",zoneID=85},questType="standard"},
[6324] = {id=6324,name="Return to Morris",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=85,description="The bat master in Brill is Bat Handler Anette. If you have already met her, then I can give you a bat to fly back to her. Our bats will always fly to the Undercity, but to travel to more remote locales their rider must first visit the area and speak with its bat master. You have met Anette in Brill, so you may now fly bats there. Speak with me again when you are ready.",starts={{npcID=4551,x=0.63,y=0.482,zoneID=1497}},ends={{npcID=1745,x=0.602,y=0.524,zoneID=85}},coords={x=0.63,y=0.482,source="quest_giver",zoneID=1497},questType="standard"},
[6341] = {id=6341,name="To Darnassus",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1657,description="Everyone in Dolanaar is so proud of Sister Aquinne . I'm certain she'll be pleased to receive this thoughtful gift from Nyoma. When you're ready to travel to Darnassus, just speak to me again and for a few coins, you can hire a hippogryph to take you there. I'm told Sister Aquinne enjoys the solitude of a small plaza just south of the hippogryph master in Darnassus. Look for her there after you arrive.",starts={{npcID=40553,x=0.554,y=0.504,zoneID=141}},ends={{npcID=7316,x=0.362,y=0.532,zoneID=1657}},coords={x=0.554,y=0.504,source="quest_giver",zoneID=141},questType="standard"},
[6342] = {id=6342,name="An Unexpected Gift",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1657,description="This is wonderful! It's just the kind of thing I need to remind me of home while I continue my studies in the Temple of the Moon. I'll try out one of the recipes tonight. I can't wait! Would you take this short note of thanks back to Nyoma? You can hire a hippogryph to take you back to Dolanaar. Just visit our hippogryph master, Leora , when you're ready to leave. She'll help you get a ride back to Dolanaar.",starts={{npcID=7316,x=0.362,y=0.532,zoneID=1657}},ends={{npcID=40552,x=0.366,y=0.48,zoneID=1657}},coords={x=0.362,y=0.532,source="quest_giver",zoneID=1657},questType="standard"},
[6343] = {id=6343,name="Return to Nyoma",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,description="It will be easy to get you a flight back to Dolanaar. Since you already know Fidelio in Dolanaar, you'll be able to fly back there without any problems. Whenever you arrive in a new town, you should remember to speak to the flight master so that you can fly to and from the new location. Speak with me when you're ready to hire a hippogryph to return to Dolanaar.",starts={{npcID=40552,x=0.366,y=0.48,zoneID=1657}},ends={{npcID=4265,x=0.566,y=0.534,zoneID=141}},coords={x=0.366,y=0.48,source="quest_giver",zoneID=1657},questType="standard"},
[6344] = {id=6344,name="Reminders of Home",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,description="A friend of mine, Sister Aquinne, is training to be a priestess of the moon in Darnassus. She left Dolanaar to study in the temple last year. Her letters say she is doing well and learning much, but she misses home and her old friends. I've put together a book of her favorite recipes from Dolanaar. If you have time, would you take them to her in Darnassus? You can rent a hippogryph from Fidelio . He's in the center of town, just across from the inn.",starts={{npcID=4265,x=0.566,y=0.534,zoneID=141}},ends={{npcID=40553,x=0.554,y=0.504,zoneID=141}},coords={x=0.566,y=0.534,source="quest_giver",zoneID=141},questType="standard"},
[6361] = {id=6361,name="A Bundle of Hides",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=215,description="I have a bundle of hides from the animals of Mulgore , and must get them to Thunder Bluff. A colleague there, Ahanu, will use the hides to create leather goods. Will you take the hides to him for me? The quickest way to Thunder Bluff is on the back of a wind rider. Bring the bundle of hides to Tak , our wind rider master in Bloodhoof Village, and speak to him about transport to Thunder Bluff.",starts={{npcID=3079,x=0.46,y=0.582,zoneID=215}},ends={{npcID=40809,x=0.474,y=0.586,zoneID=215}},coords={x=0.46,y=0.582,source="quest_giver",zoneID=215},questType="standard"},
[6362] = {id=6362,name="Ride to Thunder Bluff",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1638,description="For a small fee, I will give you a wind rider to Thunder Bluff. There's no faster way to the city! If that is acceptable, speak to me again when you are ready to go. If you're taking those hides to Ahanu , then I think he's at Hewa's Armory, at the base of the wind rider tower in Thunder Bluff. And that's right where you'll land!",starts={{npcID=40809,x=0.474,y=0.586,zoneID=215}},ends={{npcID=8359,x=0.454,y=0.558,zoneID=1638}},coords={x=0.474,y=0.586,source="quest_giver",zoneID=215},questType="standard"},
[6363] = {id=6363,name="Tal the Wind Rider Master",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1638,description="I have prepared leather goods for Varg to sell at the Bloodhoof Village. Will you bring them to him? If you have already been to Bloodhoof Village and spoken to their wind rider master, then you can fly one of our Thunder Bluff wind riders back to him. Take the leather goods to Tal , our wind rider master in Thunder Bluff, and speak with him to arrange transport to Bloodhoof Village.",starts={{npcID=8359,x=0.454,y=0.558,zoneID=1638}},ends={{npcID=2995,x=0.468,y=0.498,zoneID=1638}},coords={x=0.454,y=0.558,source="quest_giver",zoneID=1638},questType="standard"},
[6364] = {id=6364,name="Return to Varg",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=215,description="In order to fly to a town, you must have already been there and spoken with the wind rider master of that town. You have been to the Bloodhoof Village and spoken to their wind rider master Tak, so for a small fee you can take a wind rider to him from here. Speak with me again when you are ready. Once at Bloodhoof Village, you can then deliver the leather goods to Varg Windwhisper .",starts={{npcID=2995,x=0.468,y=0.498,zoneID=1638}},ends={{npcID=3079,x=0.46,y=0.582,zoneID=215}},coords={x=0.468,y=0.498,source="quest_giver",zoneID=1638},questType="standard"},
[6384] = {id=6384,name="Ride to Orgrimmar",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1637,description="For just a few coins I will have a wind rider bring you to Orgrimmar. When you get there, you can take Grimtak's meats to Gryshka. Her inn is in the Valley of Strength. Speak with me again when you are ready for the journey.",starts={{npcID=3615,x=0.486,y=0.586,zoneID=17},{npcID=41140,x=0.53,y=0.436,zoneID=14}},ends={{npcID=6929,x=0.534,y=0.788,zoneID=1637}},coords={x=0.486,y=0.586,source="quest_giver",zoneID=17},questType="standard"},
[6385] = {id=6385,name="Doras the Wind Rider Master",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1637,description="I've written a letter of thanks to Grimtak. Will you deliver it for me? If you've already been to the Razor Hill and spoken with their wind rider master, then you can fly a wind rider back there. Take my letter to Doras , the wind rider master of Orgrimmar, and speak with him about transport to Razor Hill.",starts={{npcID=6929,x=0.534,y=0.788,zoneID=1637}},ends={{npcID=3310,x=0.494,y=0.592,zoneID=1637}},coords={x=0.534,y=0.788,source="quest_giver",zoneID=1637},questType="standard"},
[6386] = {id=6386,name="Return to Razor Hill",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=14,description="My wind riders are trained to fly to many different places, as long as you have already been to that place and spoken with the wind rider master there. You have been to Razor Hill and spoken to their wind rider master Burok, so now you can fly directly to him from here. Once you're at Razor Hill, you can deliver Gryshka's letter to Grimtak . Speak with me when you are ready to go.",starts={{npcID=3310,x=0.494,y=0.592,zoneID=1637}},ends={{npcID=3489,x=0.506,y=0.578,zoneID=17},{npcID=3881,x=0.508,y=0.428,zoneID=14}},coords={x=0.494,y=0.592,source="quest_giver",zoneID=1637},questType="standard"},
[6387] = {id=6387,name="Honor Students",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1,description="I see a lot of young dwarves at my door, eager to learn the trade of cooking. And if there's one thing a cook needs more than anything, it's a cleaver! I have a list of students who scored high in their lessons and earned an honorary cleaver. Take my list to Golnir Bouldertoe in Ironforge. He'll get the cleavers ready. The fastest way to Ironforge is on a gryphon, so bring the list to our gryphon master, Brolan Galebeard , and speak with him about transport to Ironforge.",starts={{npcID=1699,x=0.546,y=0.506,zoneID=1}},ends={{npcID=43701,x=0.538,y=0.526,zoneID=1}},coords={x=0.546,y=0.506,source="quest_giver",zoneID=1},questType="standard"},
[6388] = {id=6388,name="Gryth Thurden",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1537,description="Here are the honorary cleavers for Gremlock's students. If you've already been to Kharanos, then you should fly a gryphon back there! Take the cleavers to our gryphon master, Gryth Thurden , and speak with him about a ride back to Kharanos.",starts={{npcID=4256,x=0.51,y=0.262,zoneID=1537}},ends={{npcID=1573,x=0.558,y=0.478,zoneID=1537}},coords={x=0.51,y=0.262,source="quest_giver",zoneID=1537},questType="standard"},
[6391] = {id=6391,name="Ride to Ironforge",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1537,description="For just a few coins, one of my gryphons will take you to Ironforge. From there, deliver Gremlock's list to Golnir Bouldertoe . You'll find him in the Deep Mountain Mining Guild. That's in the Great Forge District of Ironforge, which is right where my gryphon will drop you off! Speak to me again when you're ready for the journey.",starts={{npcID=43701,x=0.538,y=0.526,zoneID=1}},ends={{npcID=4256,x=0.51,y=0.262,zoneID=1537}},coords={x=0.538,y=0.526,source="quest_giver",zoneID=1},questType="standard"},
[6392] = {id=6392,name="Return to Gremlock",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1,description="For a small fee you can buy a gryphon ride to Kharanos... as long as you've already been there. Gryphons will only fly you to places you've already been, so be sure to speak with every gryphon master you see so you can fly to him later. You've already been to Brolan, the gryphon master of Kharanos, so now you can return to him. And once in Kharanos, you can deliver the cleavers to Gremlock Pilsnor . Speak with me when you're ready to go.",starts={{npcID=1573,x=0.558,y=0.478,zoneID=1537}},ends={{npcID=1699,x=0.546,y=0.506,zoneID=1}},coords={x=0.558,y=0.478,source="quest_giver",zoneID=1537},questType="standard"},
[6441] = {id=6441,name="Satyr Horns",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=331,description="Heya! I've been traveling through Ashenvale , heading towards Ratchet, and decided to make a stop here at Splintertree. I'm always looking for an opportunity, and it seems that satyr horns are in high demand in Ratchet these days. After asking around here, it seems that the satyrs in Night Run, Satyrnaar, and Xavian all have the type of horns I am looking for. I'm no match for those satyrs... but you look like you might be! Tell you what, you collect the horns for me and I'll make it worth your time.",starts={{npcID=12724,x=0.738,y=0.624,zoneID=331}},ends={{npcID=12724,x=0.738,y=0.624,zoneID=331}},coords={x=0.738,y=0.624,source="quest_giver",zoneID=331},questType="standard"},
[6442] = {id=6442,name="Naga at the Zoram Strand",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=719,description="There is evil lurking here along the coast, . It is the resting place of the doomed city of Zoram, long destroyed and submerged beneath the seas. Lost, and nearly forgotten. Now, the naga have returned, and for what reason we do not know. But reason matters little; we must defend the land we have worked so hard to claim as our own. Return to me with 20 of their heads! Throw the naga back to the depths!",starts={{npcID=12719,x=0.126,y=0.352,zoneID=331}},ends={{npcID=12719,x=0.126,y=0.352,zoneID=331}},coords={x=0.126,y=0.352,source="quest_giver",zoneID=331},questType="standard"},
[6462] = {id=6462,name="Troll Charm",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=1,description="My kinfolk were traveling here with many sacred troll charms , but the Thistlefur furbolgs attacked and killed them before they reached Zoram'gar! Those vile furbolgs! I miss my brothers and sisters who were killed, but we will meet again in the afterlife. However, their troll charms hold great value in this world. It is an outrage that the furbolgs have them! , you must retrieve the charms! They are in chests in Thistlefur Hold, a cave at the end of Thistlefur Village, north of Astranaar.",starts={{npcID=12721,x=0.388,y=0.424,zoneID=331}},ends={{npcID=12721,x=0.388,y=0.424,zoneID=331}},coords={x=0.388,y=0.424,source="quest_giver",zoneID=331},questType="standard"},
[6482] = {id=6482,name="Freedom to Ruul",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=331,description="Eh? Who are you? ? You're no furbolg. They are cursed! They thought I was a bear and captured me, and now they starve me! My strength is failing... Help me escape, then speak with my sister Yama at the Splintertree Post to the east. ! I must escape!",starts={{npcID=12818,x=0.414,y=0.346,zoneID=331}},ends={{npcID=12837,x=0.74,y=0.608,zoneID=331}},coords={x=0.414,y=0.346,source="quest_giver",zoneID=331},questType="standard"},
[6503] = {id=6503,name="Ashenvale Outrunners",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=331,description="Blasted elves! Dey knew right where to hit us! It was dem outrunners... I tried to warn 'em that we were being spied on, but no one listened. Now look at us - cooped up here like chickens! Never too late for vengeance, mon! Hunt 'em down and make 'em pay for what they done!",starts={{npcID=12867,x=0.734,y=0.608,zoneID=331}},ends={{npcID=12867,x=0.734,y=0.608,zoneID=331}},coords={x=0.734,y=0.608,source="quest_giver",zoneID=331},questType="standard"},
[6544] = {id=6544,name="Torek's Assault",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=331,description="Hey! ! Come here! My raiders and I are about to attack the Silverwing Outpost to the west. Our target is its leader, Duriel Moonfire. Scouts report the outpost is defended heavily with sentinels and warriors. The battle will be glorious! Do you want to share in the glory, , and aid us? If so, then when it's over you can report our success to my superior, Ertog Ragetusk in Splintertree. What do you say. Are you with us?",starts={{npcID=12858,x=0.684,y=0.752,zoneID=331}},ends={{npcID=12877,x=0.73,y=0.624,zoneID=331}},coords={x=0.684,y=0.752,source="quest_giver",zoneID=331},questType="standard"},
[6607] = {id=6607,name="Nat Pagle, Angler Extreme",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=15,description="Can't say I really enjoy fishin' much. Figure I been at it for a good 20 or 30 years now. I reckon people are driven to do what they do for different reasons. Now, I'm not saying you need to fish for 30 years or catch every fish in the sea to become a master fisherman. I reckon you just need to be determined - determined enough to sit on your duff for hours at a time, doin' nothin'. I'll tell you what, catch me a few rare fish and I'll teach you a thing or two. Here's a list:",starts={{npcID=12919,x=0.586,y=0.602,zoneID=15}},ends={{npcID=12919,x=0.586,y=0.602,zoneID=15}},coords={x=0.586,y=0.602,source="quest_giver",zoneID=15},questType="standard"},
[6610] = {id=6610,name="Clamlette Surprise",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=440,description="Ever heard of a clamlette? Of course you haven't! It's my latest and greatest culinary masterpiece. Oh, , just thinking about a clamlette makes my mouth water. Unfortunately, I'm all out of supplies to make any! How about I make you a deal? You gather the supplies I need to make a clamlette and I'll teach you the finer points of exotic cuisine and I'll even throw in a couple of clamlettes to boot! Deal?? Here's what I need:",starts={{npcID=40589,x=0.524,y=0.29,zoneID=440}},ends={{npcID=40589,x=0.524,y=0.29,zoneID=440}},coords={x=0.524,y=0.29,source="quest_giver",zoneID=440},questType="standard"},
[6611] = {id=6611,name="To Gadgetzan You Go!",level=15,requiredLevel=15,faction="horde",expansion=0,zoneID=440,description="How you expect Zamja teach you anything? You got all of Zamja 's cooking mojo and still you crave more! Zamja can't help. Fat needs to go to Gadgetzan. You find a little goblin named Dirge there - he help you, fatty. When you become big cook on the block, you come back and teach Zamja , ok? Now go!",starts={{npcID=3399,x=0.322,y=0.694,zoneID=1637}},ends={{npcID=40589,x=0.524,y=0.29,zoneID=440}},coords={x=0.322,y=0.694,source="quest_giver",zoneID=1637},questType="standard"},
[6621] = {id=6621,name="King of the Foulweald",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=331,description="My research has paid off. I believe that with a show of force, we can diminish the furbolgs' aggressiveness. Take this banner a short ways northeast and place it on their totem mound. They will try to destroy the banner, but hold your ground until their chief, Murgut, appears to save face for the tribe. Bring me the totem he carries. Gather your allies, . This is no task for a single .",starts={{npcID=12696,x=0.498,y=0.652,zoneID=331}},ends={{npcID=12696,x=0.498,y=0.652,zoneID=331}},coords={x=0.498,y=0.652,source="quest_giver",zoneID=331},questType="standard"},
[6622] = {id=6622,name="Triage",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=45,description="Good day, doctor. You will be tested on your ability to triage patients accordingly this afternoon. Should you pass your examination, you will join the prestigious ranks of Horde Trauma. Now pay attention! The critically injured must be tended to first. After the criticals come the badly injured. The injured should be tended to last. You must save 15 patients to pass this exam. You will fail should 6 of your patients die in triage. Triage bandages will be supplied. Good luck, doctor.",starts={{npcID=12920,x=0.684,y=0.378,zoneID=45}},ends={{npcID=12920,x=0.684,y=0.378,zoneID=45}},coords={x=0.684,y=0.378,source="quest_giver",zoneID=45},questType="standard"},
[6623] = {id=6623,name="Horde Trauma",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=45,description="Doctor , I presume. It is a pleasure to see you again. I have some wonderful news for you! Doctor Gregory Victor , chief physician of Horde Trauma has made a personal request for you to join him at Hammerfall. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great Doctor Gregory Victor ! Do not squander this opportunity!",starts={{npcID=45540,x=0.37,y=0.872,zoneID=1637}},ends={{npcID=12920,x=0.684,y=0.378,zoneID=45}},coords={x=0.37,y=0.872,source="quest_giver",zoneID=1637},questType="standard"},
[6624] = {id=6624,name="Triage",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=6040,description="Good day, doctor. You will be tested on your ability to triage patients accordingly this afternoon. Should you pass your examination, you will join the prestigious ranks of Alliance Trauma. Now pay attention! The critically injured must be tended to first. After the criticals come the badly injured. The injured should be tended to last. You must save 15 patients to pass this exam. You will fail should 6 of your patients die in triage. Good luck, doctor.",starts={{npcID=12939,x=0.676,y=0.488,zoneID=15}},ends={{npcID=12939,x=0.676,y=0.488,zoneID=15}},coords={x=0.676,y=0.488,source="quest_giver",zoneID=15},questType="standard"},
[6625] = {id=6625,name="Alliance Trauma",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=15,description="Doctor , I presume. It is a pleasure to see you. I have some wonderful news for you! Gustaf VanHowzen, chief physician of Alliance Trauma has made a personal request for you to join him at Theramore. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great doctor, Gustaf VanHowzen! Do not squander this opportunity, doctor!",starts={{npcID=5150,x=0.548,y=0.586,zoneID=1537}},ends={{npcID=12939,x=0.676,y=0.488,zoneID=15}},coords={x=0.548,y=0.586,source="quest_giver",zoneID=1537},questType="standard"},
[6641] = {id=6641,name="Vorsha the Lasher",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=331,description="Vorsha the Lasher... the fiendish hydra that roams the seas... She has attacked our outpost, each time unprovoked, laying waste to anything that falls in her path. But I am ready, . I have prepared to best the hydra and end these attacks on Zoram'gar. The naga honor the wicked nature of this beast with a brazier that remains lit on an island just off the coast. I believe that if we put it out, Vorsha will appear in anger. We will need help, so be sure to bring some strong allies.",starts={{npcID=12717,x=0.126,y=0.342,zoneID=331}},ends={{npcID=12863,x=0.124,y=0.35,zoneID=331}},coords={x=0.126,y=0.342,source="quest_giver",zoneID=331},questType="group"},
