[6646] = {id=6646,name="Favor Amongst the Brotherhood, Blood of the Mountain",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=2717,questType="dungeon"},
[6661] = {id=6661,name="Deeprun Rat Roundup",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=2257,description="Avast ye scallywag. Arrrr... Arrrr ye looking fer work? We gots a serious rat problem down here an' not enough hands on the poop deck. What do ye say? All ye needs to do is take this here rat catchin' flute and play the melody around the vermin. They'll follow ye to the ends of the world! Just capture five of the little buggers and bring em back here. We needs em alive. Arrrrr...",questType="standard"},
[6662] = {id=6662,name="Me Brother, Nipsy",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=2257,description="Me brother, Nipsy , runs a rat kabob operation on the other side of Deeprun. Ye needs to take this here crate o' rats to him before they go bad. Get a move on! Ye have ridden a tram before, aye? It's easy. Just step aboard when she arrives and enjoy the ride. An' keep yer arms and legs inside durin' the ride, lest ye be peglegged fer life.",questType="standard"},
[6741] = {id=6741,name="More Booty!",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,starts={{npcID=13176,x=0.496,y=0.826,zoneID=2597},{npcID=13176,zoneID=10458}},ends={{npcID=13176,x=0.496,y=0.826,zoneID=2597},{npcID=13176,zoneID=10458}},coords={x=0.496,y=0.826,source="quest_giver",zoneID=2597},questType="standard"},
