[6827] = {id=6827,name="Call of Air - Mulverick's Fleet",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,starts={{npcID=13181,zoneID=2597},{npcID=13181,zoneID=10458}},ends={{npcID=13181,zoneID=2597},{npcID=13181,zoneID=10458}},questType="pvp"},
[6847] = {id=6847,name="Master Ryson's All Seeing Eye",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=2597,description="Your war in the heart of Alterac means nothing to the Syndicate, . We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike. That, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region. Recover the Eye and our services shall be yours - for whatever time remains for your side. Return to me once you acquire the eye so that I may examine you.",questType="pvp"},
[6881] = {id=6881,name="Ivus the Forest Lord",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,starts={{npcID=13442,zoneID=2597},{npcID=13442,zoneID=10458}},ends={{npcID=13442,zoneID=2597},{npcID=13442,zoneID=10458}},questType="pvp"},
