[6943] = {id=6943,name="Call of Air - Ichman's Fleet",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,starts={{npcID=13437,x=0.484,y=0.846,zoneID=2597},{npcID=13437,zoneID=10458}},ends={{npcID=13437,x=0.484,y=0.846,zoneID=2597},{npcID=13437,zoneID=10458}},coords={x=0.484,y=0.846,source="quest_giver",zoneID=2597},questType="pvp"},
[6961] = {id=6961,name="Great-father Winter is Here!",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1637,description="Have a wondrous Winter Veil, friend! Be sure to say hello to Great-father Winter ! If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil. Be sure to tell him what you hope to get this year! Also, be sure to stock up on treats to give those who've been nice this year. We have a great selection to choose from. Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!",starts={{npcID=13418,x=0.524,y=0.77,zoneID=1637}},ends={{npcID=13445,x=0.498,y=0.78,zoneID=1637}},coords={x=0.524,y=0.77,source="quest_giver",zoneID=1637},questType="standard"},
[6962] = {id=6962,name="Treats for Great-father Winter",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1637,description="Hey, can you do Great-father Winter a favor, um, little ? Not to needlessly talk about myself in the third person, but Great-father Winter has been at this all day and he could use a treat himself. Some gingerbread cookies and ice cold milk to wash them down with would really hit the spot. Think you could be a friend to the Great-father and fetch some for me?",starts={{npcID=13445,x=0.498,y=0.78,zoneID=1637}},ends={{npcID=13445,x=0.498,y=0.78,zoneID=1637}},coords={x=0.498,y=0.78,source="quest_giver",zoneID=1637},questType="standard"},
[6964] = {id=6964,name="The Reason for the Season",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1637,description="Gifts, treats, presents... bah, I say! Those goblins pollute the true meaning of this season - the Feast of Winter Veil. This is a time of renewal; the land slumbers under a blanket of snow brought forth by Greatfather Winter, who is NOT the bumbling fool over there in the red suit! If you're interested in learning what the Feast is all about for yourself, ask Sagorne Creststrider . I'm sure he'll be surprised that someone cares about history rather than getting presents.",starts={{npcID=9550,x=0.51,y=0.712,zoneID=1637}},ends={{npcID=13417,x=0.396,y=0.474,zoneID=1637}},coords={x=0.51,y=0.712,source="quest_giver",zoneID=1637},questType="standard"},
[6982] = {id=6982,name="Coldtooth Supplies",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,description="The Coldtooth mine is a storage depot for the Horde. I can't stomach the food they give their troops, and the state of their arms and armor is atrocious! But... in times like these when supplies are so important, we can use what they have. Enter the Coldtooth mine and bring me back their supplies. That will help keep the Alliance in fighting shape, and remove much needed equipment from the Horde's warriors. Good luck, . The mine is to the distant south, deep in Horde territory.",starts={{npcID=12096,zoneID=2597},{npcID=12096,zoneID=10458}},ends={{npcID=12096,zoneID=2597},{npcID=12096,zoneID=10458}},questType="pvp"},
[6983] = {id=6983,name="You're a Mean One...",level=30,requiredLevel=30,faction="horde",expansion=0,zoneID=17,description="A creature called \"The Abominable Greench\" stole our shipment of treats, . Be careful though! He's vicious and a bunch of those little green gnomes do his bidding! You're gonna need some help in facing him. Rumor has it he's holding our treats and our beloved Metzen the Reindeer at Growless Cave in the Hillsbrad Foothills! Find the treats and bring them back before the celebration is ruined and all the children of Orgrimmar are disappointed!",starts={{npcID=13418,x=0.524,y=0.77,zoneID=1637},{npcID=13636,x=0.424,y=0.41,zoneID=267}},ends={{npcID=13418,x=0.524,y=0.77,zoneID=1637}},coords={x=0.524,y=0.77,source="quest_giver",zoneID=1637},questType="group"},
[6984] = {id=6984,name="A Smokywood Pastures' Thank You!",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1637,description="We at Smokywood Pastures appreciate the recovery of the stolen treats, . For that, we'd like to offer you a special gift... presented by none other than Great-father Winter himself! Please, speak with Great-father Winter , and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures. From our farm to your plate, it's always Smokywood Pastures wholesome goodness... thanks to you, of course!",starts={{npcID=13418,x=0.524,y=0.77,zoneID=1637}},ends={{npcID=13445,x=0.498,y=0.78,zoneID=1637}},coords={x=0.524,y=0.77,source="quest_giver",zoneID=1637},questType="standard"},
[6985] = {id=6985,name="Irondeep Supplies",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,description="The Stormpike dwarves are using the Irondeep mine as a storage depot. I want you to raid that mine and bring me its supplies. This will curtail the Stormpikes' efforts in Alterac Valley , and will provide us with needed equipment! Be wary, . The Irondeep mine is deep in Alliance territory, and control of the mine is as shifting as the snows of Alterac.",starts={{npcID=12097,x=0.466,y=0.84,zoneID=2597},{npcID=12097,zoneID=10458}},ends={{npcID=12097,x=0.466,y=0.84,zoneID=2597},{npcID=12097,zoneID=10458}},coords={x=0.466,y=0.84,source="quest_giver",zoneID=2597},questType="pvp"},
[7001] = {id=7001,name="Empty Stables",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=2597,description="The war in the valley has taken its toll on our soldiers. We must revitalize our forces! If we can fill up the stables, the Wolf Riders will once more be able to ride out into the field of battle. Take this muzzle and track down the frostwolves that inhabit the nearby forest. Once you find a wolf, use the muzzle to tame the beast. Bring the tamed beast back to me so that I may place it in the stable. When we have enough wolves stabled, the Wolf Riders will rejoin their patrol on our front lines.",starts={{npcID=13616,zoneID=2597}},ends={{npcID=13616,zoneID=2597}},questType="standard"},
[7002] = {id=7002,name="Ram Hide Harnesses",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,starts={{npcID=13441,zoneID=2597},{npcID=13441,zoneID=10458}},ends={{npcID=13441,zoneID=2597},{npcID=13441,zoneID=10458}},questType="pvp"},
[7021] = {id=7021,name="Great-father Winter is Here!",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1637,description="Have a wondrous Winter Veil, friend! Be sure to say hello to Great-father Winter , who's currently in Orgrimmar! If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil. Be sure to tell him what you hope to get this year! Also, be sure to stock up on treats to give those who've been nice this year. We have a great selection to choose from. Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!",starts={{npcID=13431,x=0.424,y=0.556,zoneID=1638}},ends={{npcID=13445,x=0.498,y=0.78,zoneID=1637}},coords={x=0.424,y=0.556,source="quest_giver",zoneID=1638},questType="standard"},
[7022] = {id=7022,name="Greatfather Winter is Here!",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1537,description="Have a wondrous Winter Veil, friend! Be sure to say hello to Greatfather Winter ! If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil. Be sure to tell him what you hope to get this year! Also, be sure to stock up on treats to give those who've been nice this year. We have a great selection to choose from. Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!",starts={{npcID=13433,x=0.332,y=0.678,zoneID=1537}},ends={{npcID=13444,x=0.332,y=0.658,zoneID=1537}},coords={x=0.332,y=0.678,source="quest_giver",zoneID=1537},questType="standard"},
