[7026] = {id=7026,name="Ram Riding Harnesses",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,starts={{npcID=13577,zoneID=2597},{npcID=13577,zoneID=10458}},ends={{npcID=13577,zoneID=2597},{npcID=13577,zoneID=10458}},questType="pvp"},
[7027] = {id=7027,name="Empty Stables",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=2597,description="Just look at the stables, ! Empty! The Stormpike Brigade has no rams to ride - the cavalry is defunct. You must help us, soldier. Take this training collar and enter the wilds of this valley. Locate the Alterac rams that roam throughout the area and use the collar to snare one. When you have captured a ram, return it to me and I shall place it in our stable. When we have enough rams, the ram rider commander will be notifed. With your help, the cavalry will be reborn!",starts={{npcID=13617,zoneID=2597}},ends={{npcID=13617,zoneID=2597}},questType="standard"},
[7043] = {id=7043,name="You're a Mean One...",level=30,requiredLevel=30,faction="alliance",expansion=0,zoneID=17,description="A creature called \"The Abominable Greench\" stole our shipment of treats, . Be careful though! He's vicious and a bunch of those little green gnomes do his bidding! You're gonna need some help in facing him. Rumor has it he's holding our treats and our beloved Metzen the Reindeer at Growless Cave in the Hillsbrad Foothills! Find the treats and bring them back before the celebration is ruined and all the children of Stormwind are disappointed!",starts={{npcID=13433,x=0.332,y=0.678,zoneID=1537},{npcID=13636,x=0.424,y=0.41,zoneID=267}},ends={{npcID=13433,x=0.332,y=0.678,zoneID=1537}},coords={x=0.332,y=0.678,source="quest_giver",zoneID=1537},questType="group"},
[7045] = {id=7045,name="A Smokywood Pastures' Thank You!",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1537,description="We at Smokywood Pastures appreciate the recovery of the stolen treats, . For that, we'd like to offer you a special gift... presented by none other than Greatfather Winter himself! Please, speak with Greatfather Winter , and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures. From our farm to your plate, it's always Smokywood Pastures wholesome goodness... thanks to you, of course!",starts={{npcID=13433,x=0.332,y=0.678,zoneID=1537}},ends={{npcID=13444,x=0.332,y=0.658,zoneID=1537}},coords={x=0.332,y=0.678,source="quest_giver",zoneID=1537},questType="standard"},
[7061] = {id=7061,name="The Feast of Winter Veil",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1637,description="Here - if you are interested in learning more about the Feast of Winter Veil , read this book. While I think our recognition of the legend is the appropriate one, I'm enough of a student of legends to appreciate the collection of all information into a single source. When you're done, take the book to Baine Bloodhoof in Thunder Bluff. I know for a fact he'd be interested in hearing that others have taken an interest in the lore of our people.",starts={{npcID=13417,x=0.396,y=0.474,zoneID=1637}},coords={x=0.396,y=0.474,source="quest_giver",zoneID=1637},questType="standard"},
[7062] = {id=7062,name="The Reason for the Season",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1537,description="Gifts, treats, presents... bah, I say! Those goblins pollute the true meaning of this season - the Feast of Winter Veil. This is a time of renewal; the land slumbers under a blanket of snow brought forth by Greatfather Winter, who is NOT the bumbling fool over there in the red suit! If you're interested in learning what the Feast is all about for yourself, ask Historian Karnik at the Explorers' League. I'm sure he'll be surprised that someone cares about history rather than getting presents.",starts={{npcID=1365,x=0.302,y=0.598,zoneID=1537}},ends={{npcID=2916,x=0.77,y=0.118,zoneID=1537}},coords={x=0.302,y=0.598,source="quest_giver",zoneID=1537},questType="standard"},
[7063] = {id=7063,name="The Feast of Winter Veil",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1537,description="Here - if you are interested in learning more about the Feast of Winter Veil , read this book. While I think our recognition of the legend is the appropriate one, I'm enough of a scholar to appreciate the collection of all information into a single source. When you're done, take the book to Muradin Bronzebeard . I know for a fact he'd be interested in hearing that others have taken an interest in the older legends.",starts={{npcID=2916,x=0.77,y=0.118,zoneID=1537}},ends={{npcID=42928,x=0.394,y=0.558,zoneID=1537}},coords={x=0.77,y=0.118,source="quest_giver",zoneID=1537},questType="standard"},
[7081] = {id=7081,name="Alterac Valley Graveyards",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=267,description="The graveyards in Alterac Valley are prized territories. Both the Horde and the Alliance fight savagely for these sacred grounds. Are you, , ready to join that fight? I want you to assault an enemy graveyard. Find a graveyard with a Horde banner in its midst, and pull it from the ground! Do that, and your task will be complete.... But if you can also hold the graveyard for a few minutes, then our troops will soon come to relieve you.",starts={{npcID=13777,x=0.43,y=0.438,zoneID=267}},ends={{npcID=13777,x=0.43,y=0.438,zoneID=267}},coords={x=0.43,y=0.438,source="quest_giver",zoneID=267},questType="pvp"},
[7082] = {id=7082,name="The Graveyards of Alterac",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=2597,description="The battle lines of Alterac Valley are ever shifting. Territories swing back and forth as we meet our opponents in deadly combat. And graveyards, , are where battles rage most fierce. I want you to attack an Alliance held graveyard! Find a graveyard with an Alliance banner in its midst and pull it from the ground. Do that and your task for me will be complete, but... if you hold the graveyard for a few minutes, then it will be ours and troops will come and relieve you.",questType="pvp"},
[7101] = {id=7101,name="Towers and Bunkers",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=2597,description="Towers and bunkers are important positions, and we must capture and hold them all! So to that end, I want you to attack a bunker that is controlled by the enemy. To do that, enter one with an Alliance banner. You will see another banner inside. Pull out that banner, and a white Horde banner will appear in its place. Well done! At that point your task for me will be complete, but if you hold the place long enough, and if the Alliance doesn't take it back, then it will be destroyed!",questType="pvp"},
[7102] = {id=7102,name="Towers and Bunkers",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=267,description="Towers and bunkers are key defensive positions, and so we must hold as many as possible! I want you to attack a tower or a bunker in Alterac Valley . To do that, enter a tower with a Horde banner atop it. You will see another enemy banner inside. Pull out that banner, and a white Alliance banner will appear in its place. Well done! At that point your mission for me will be complete, but hold the area long enough, and if the Horde doesn't take it back, then it will be destroyed!",starts={{npcID=13777,x=0.43,y=0.438,zoneID=267}},ends={{npcID=13777,x=0.43,y=0.438,zoneID=267}},coords={x=0.43,y=0.438,source="quest_giver",zoneID=267},questType="pvp"},
[7121] = {id=7121,name="The Quartermaster",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,description=", our quartermaster charged me to direct new recruits to him. He needs supplies from caches stored in the mines of Alterac, and he'll probably send you to get them. Follow the road. You'll find our quartermaster to the west.",starts={{npcID=13797,zoneID=2597},{npcID=13797,zoneID=10458}},ends={{npcID=12096,zoneID=2597},{npcID=12096,zoneID=10458}},questType="pvp"},
[7122] = {id=7122,name="Capture a Mine",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=267,description="The mines in Alterac Valley hold more than just minerals. Both the Frostwolf and Stormpike have cached excess supplies in the Irondeep and Coldtooth mines... that's not a bad idea, if we could only maintain control of them! Capture a mine, then return to me. To capture a mine, enter one that we do not control and kill its leader. When you do that, the mine will be ours, and we'll send troops to protect it!",starts={{npcID=13777,x=0.43,y=0.438,zoneID=267}},ends={{npcID=13777,x=0.43,y=0.438,zoneID=267}},coords={x=0.43,y=0.438,source="quest_giver",zoneID=267},questType="pvp"},
[7123] = {id=7123,name="Speak with our Quartermaster",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,description=", the Frostwolf Quartermaster is looking for recruits, for tasks that lead into the mines of Alterac Valley . Speak with him; he will tell you more. Follow the road west into the bunker, then take the west exit and you'll find our quartermaster.",starts={{npcID=13798,zoneID=2597},{npcID=13798,zoneID=10458}},ends={{npcID=12097,x=0.466,y=0.84,zoneID=2597},{npcID=12097,zoneID=10458}},questType="pvp"},
[7124] = {id=7124,name="Capture a Mine",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,description="As battle rages over the landscape of Alterac Valley , so too does it rage through the Coldtooth and Irondeep mines. Both are rich sources of minerals and both are used to store supplies; it's no wonder they are so highly valued! Help our war effort, ! Capture one of the mines for the Horde! To capture a mine, enter one that we do not control and kill its leader. When that is done, the mine will be ours and we'll send troops to protect it!",starts={{npcID=12097,x=0.466,y=0.84,zoneID=2597},{npcID=12097,zoneID=10458}},coords={x=0.466,y=0.84,source="quest_giver",zoneID=2597},questType="pvp"},
[7141] = {id=7141,name="The Battle of Alterac",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=2597,description="The Explorers' League believes there are artifacts in Alterac Valley , but the Frostwolf orcs won't let us explore. We can't allow the Horde to stop our scholarly pursuits! Defeat the Frostwolf general, Drek'Thar. With him dead, the orcs will lose their edge. Drek'Thar is in Frostwolf Keep, in the south of Alterac Valley . Vanquish him, and then return to me.",starts={{npcID=13816,x=0.452,y=0.452,zoneID=267}},ends={{npcID=13816,x=0.452,y=0.452,zoneID=267}},coords={x=0.452,y=0.452,source="quest_giver",zoneID=267},questType="pvp"},
[7142] = {id=7142,name="The Battle for Alterac",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=2597,description="The Stormpike dwarves and their allies have invaded Alterac Valley , and we must drive them out! To win the battle for Alterac, we must defeat their general, Vanndar Stormpike! You will find Vanndar in Dun Baldar, in the north of Alterac Valley . Destroy him, , and then return to me.",starts={{npcID=13817,x=0.586,y=0.342,zoneID=267}},ends={{npcID=13817,x=0.586,y=0.342,zoneID=267}},coords={x=0.586,y=0.342,source="quest_giver",zoneID=267},questType="pvp"},
[7161] = {id=7161,name="Proving Grounds",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=267,description="Hail, . It has been a long time since we have had the chance to answer the call of battle. The old feelings are slow to rise but once awakened, the blood does rush. The battle rage returns... All newcomers to the Valley must first complete the rite of battle. Deep within the Wildpaw gnoll cave is a banner of the Frostwolf. Venture forth and recover the banner. Return it to me and I shall grant you the Frostwolf initiate's insignia.",starts={{npcID=13840,x=0.578,y=0.334,zoneID=267}},ends={{npcID=13840,x=0.578,y=0.334,zoneID=267}},coords={x=0.578,y=0.334,source="quest_giver",zoneID=267},questType="standard"},
[7162] = {id=7162,name="Proving Grounds",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=267,description="You've arrived just in time, . These Frostwolf savages just won't give up! We must show them the might of the Stormpike. They must bow to our superiority. Before you make your way to the field of battle, you will want to join the rank of Stormpike. Southwest of Dun Baldar, you will find the Icewing Caverns. Planted deep within the caverns is a Stormpike Banner . Venture forth and recover that banner. Return it to me, and you will have earned a Stormpike initiate's insignia.",starts={{npcID=13841,x=0.446,y=0.462,zoneID=267}},ends={{npcID=13841,x=0.446,y=0.462,zoneID=267}},coords={x=0.446,y=0.462,source="quest_giver",zoneID=267},questType="standard"},
[7163] = {id=7163,name="Rise and Be Recognized",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=267,starts={{npcID=13840,x=0.578,y=0.334,zoneID=267}},ends={{npcID=13840,x=0.578,y=0.334,zoneID=267}},coords={x=0.578,y=0.334,source="quest_giver",zoneID=267},questType="standard"},
