[7172] = {id=7172,name="The Eye of Command",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=267,starts={{npcID=13841,x=0.446,y=0.462,zoneID=267}},ends={{npcID=13841,x=0.446,y=0.462,zoneID=267}},coords={x=0.446,y=0.462,source="quest_giver",zoneID=267},questType="standard"},
[7223] = {id=7223,name="Armor Scraps",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,description="Battles rage constantly in Alterac Valley , and the supplies we get from Ironforge are not enough to outfit our experienced troops. If you find armor scraps from the battlefield, aid the war effort and bring those scraps to me!",starts={{npcID=13257,zoneID=2597},{npcID=13257,zoneID=10458}},ends={{npcID=13257,zoneID=2597},{npcID=13257,zoneID=10458}},questType="pvp"},
[7224] = {id=7224,name="Enemy Booty",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,description="When you fight the enemy, gather the scraps of their armor and bring them to me. I'll use those scraps to make armor for our own troops!",starts={{npcID=13176,x=0.496,y=0.826,zoneID=2597},{npcID=13176,zoneID=10458}},ends={{npcID=13176,x=0.496,y=0.826,zoneID=2597},{npcID=13176,zoneID=10458}},coords={x=0.496,y=0.826,source="quest_giver",zoneID=2597},questType="pvp"},
[7281] = {id=7281,name="Brotherly Love",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,description="Tragic... My brother faces me on the field of battle: A commander for the Stormpike. Of the four Stormpike Commanders, he is undoubtedly the most dangerous. Perhaps if he is slain, the Banshee Queen could turn him as she did me - show him the error of his ways... Deep within enemy territory you will find my brother. Slay him and return to me. I trust that you are capable of completing this mission, soldier. And soldier, do not go alone.",starts={{npcID=13154,zoneID=2597},{npcID=13154,zoneID=10458}},ends={{npcID=13154,zoneID=2597},{npcID=13154,zoneID=10458}},questType="pvp"},
[7282] = {id=7282,name="Brotherly Love",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,description="He must be put out of his misery, soldier! He knows not what he does. He has become a mindless servant of the dreaded Banshee Queen. Venture forth, across the Field of Strife, to the depths of Frostwolf territory. Find my brother and destroy him. His torment must come to an end.",starts={{npcID=13320,zoneID=2597},{npcID=13320,zoneID=10458}},ends={{npcID=13320,zoneID=2597},{npcID=13320,zoneID=10458}},questType="pvp"},
[7301] = {id=7301,name="Fallen Sky Lords",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,description="We got them held prisoner, . I'm talking about their Wing Commanders. It was a furious battle in the skies but they finally fell! Unfortunately, our best pilots were shot down in a counterattack against Frostwolf Keep. You gotta find out what happened to them. Search Tower Point West and Frostwolf Keep. These were their last known locations. Search these areas thoroughly.",starts={{npcID=13319,zoneID=2597},{npcID=13319,zoneID=10458}},ends={{npcID=13319,zoneID=2597},{npcID=13319,zoneID=10458}},questType="pvp"},
[7302] = {id=7302,name="Fallen Sky Lords",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,description="Our air support is in shambles, . The Wing Commanders were shot down over enemy territory. You must find out what became of them so that we can attempt a rescue! Guse was last seen flying over the Icewing Bunker. Jeztor's War Rider was spotted near the Stormpike lumber mill. Mulverick... that reckless fool was seen crashing near the Dun'Baldar North Bunker. That's all the information I have. Move out! Search through the areas thoroughly.",starts={{npcID=13153,zoneID=2597},{npcID=13153,zoneID=10458}},ends={{npcID=13153,zoneID=2597},{npcID=13153,zoneID=10458}},questType="pvp"},
[7383] = {id=7383,name="Teldrassil: The Burden of the Kaldorei",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,description="You must now visit the moonwell that rests under the boughs of the Oracle Tree, far to the northwest. The first and most powerful of our wells, its waters are said to possess the very essence of Elune's Powers. Retrieve a phial of its water and return to me. I will meet you at the crossroads in front of Darnassus when your task is complete.",starts={{npcID=3515,x=0.558,y=0.538,zoneID=141}},ends={{npcID=3515,x=0.558,y=0.538,zoneID=141}},coords={x=0.558,y=0.538,source="quest_giver",zoneID=141},questType="standard"},
[7385] = {id=7385,name="A Gallon of Blood",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,starts={{npcID=13236,zoneID=2597},{npcID=13236,zoneID=10458}},ends={{npcID=13236,zoneID=2597},{npcID=13236,zoneID=10458}},questType="pvp"},
[7386] = {id=7386,name="Crystal Cluster",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,starts={{npcID=13442,zoneID=2597},{npcID=13442,zoneID=10458}},ends={{npcID=13442,zoneID=2597},{npcID=13442,zoneID=10458}},questType="pvp"},
