[7604] = {id=7604,name="A Binding Contract",level=20,requiredLevel=20,faction="both",expansion=0,zoneID=2717,description="The undersigned hereby declares that the Sulfuron ingot they are delivering to the Thorium Brotherhood (TB Ltd.) is genuine and not a facsimile thereof. The undersigned also acknowledges that any harm that should come to as a result of attempting to build, forge, find, create, sell, or eat Sulfuras, is not the responsibility or fault of TB Ltd. By signing this contract, you are agreeing to all terms listed herein. _________________ Signature",questType="dungeon"},
