[7781] = {id=7781,name="The Lord of Blackrock",level=30,requiredLevel=30,faction="alliance",expansion=0,zoneID=2677,description="The old feeling returns. The welcome pangs of victory reverberate throughout your being. Before you lies the monolithic, battle scarred head of Nefarian . Bring it to the Grand Admiral on the King's behalf, champion.",ends={{npcID=1750,x=0.856,y=0.328,zoneID=1519},{npcID=29611,x=0.856,y=0.318,zoneID=1519},{npcID=107574,x=0.858,y=0.316,zoneID=1519}},questType="standard"},
[7782] = {id=7782,name="The Lord of Blackrock",level=30,requiredLevel=30,faction="alliance",expansion=0,zoneID=1519,description="Go to the Valley of Heroes and speak with Field Marshal Stonebridge .",starts={{npcID=1750,x=0.856,y=0.328,zoneID=1519},{npcID=29611,x=0.856,y=0.318,zoneID=1519},{npcID=107574,x=0.858,y=0.316,zoneID=1519}},ends={{npcID=14721,x=0.712,y=0.804,zoneID=1519}},coords={x=0.856,y=0.328,source="quest_giver",zoneID=1519},questType="standard"},
[7783] = {id=7783,name="The Lord of Blackrock",level=30,requiredLevel=30,faction="horde",expansion=0,zoneID=2677,description="The old feeling returns. The welcome pangs of victory reverberate throughout your being. Before you lies the monolithic, battle scarred head of Nefarian . Return it to the Warchief's advisor Eitrigg , champion.",ends={{npcID=3144,x=0.49,y=0.722,zoneID=1637},{npcID=14720,x=0.486,y=0.71,zoneID=1637},{npcID=39605,x=0.482,y=0.706,zoneID=1637},{npcID=86832,x=0.482,y=0.706,zoneID=1637}},questType="standard"},
[7784] = {id=7784,name="The Lord of Blackrock",level=30,requiredLevel=30,faction="horde",expansion=0,zoneID=1637,description="Seek out Overlord Natoj in the Valley of Strength.",ends={{npcID=14392,x=0.514,y=0.83,zoneID=1637}},questType="standard"},
[7785] = {id=7785,name="Examine the Vessel",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=1377,description="Examine the vessel of his rebirth, mortal. It is from this that the Windseeker shall be reborn!",ends={{npcID=14347,x=0.296,y=0.106,zoneID=1377}},questType="standard"},
[7786] = {id=7786,name="Thunderaan the Windseeker",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=2717,description="I have told you all that I know, . It is you who must find elementium. It is you who must destroy the Firelord's corporeal form. Do this and gain the blessing of Thunderaan.",starts={{npcID=14347,x=0.296,y=0.106,zoneID=1377}},ends={{npcID=14347,x=0.296,y=0.106,zoneID=1377}},coords={x=0.296,y=0.106,source="quest_giver",zoneID=1377},questType="raid"},
[7787] = {id=7787,name="Rise, Thunderfury!",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=1377,description="You have defeated the Wind Seeker. Take the dormant blade and force the lying wretch, Demitrian, to use the materials you provided for his betrayal to wake Thunderfury.",ends={{npcID=14347,x=0.296,y=0.106,zoneID=1377}},questType="standard"},
[7810] = {id=7810,name="Arena Master",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=5339,description="There must be more to being a master of the arena than this! Perhaps the Pirate who runs the event at Gurubashi will know!",ends={{npcID=14508,x=0.45,y=0.254,zoneID=5287}},questType="pvp"},
[7838] = {id=7838,name="Arena Grandmaster",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=5287,starts={{npcID=14508,x=0.45,y=0.254,zoneID=5287}},ends={{npcID=14508,x=0.45,y=0.254,zoneID=5287}},coords={x=0.45,y=0.254,source="quest_giver",zoneID=5287},questType="standard"},
[7848] = {id=7848,name="Attunement to the Core",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=51,description="Rifts stir, tear, and collapse all around us, . Not two paces from where I stand is a tear leading through the depths of Blackrock Mountain, into the maw of the Firelord. Surprised? Pity... The mortal races cannot comprehend that which they cannot see, touch, or feel. I assure you, the portal is there and access is possible. I've piqued your interest? Attunement is simple. Venture into Blackrock Depths and retrieve a core fragment . Return it to me and I shall attune your essence with the portal.",starts={{npcID=14387,x=0.182,y=0.25,zoneID=46}},ends={{npcID=14387,x=0.182,y=0.25,zoneID=46}},coords={x=0.182,y=0.25,source="quest_giver",zoneID=46},questType="dungeon"},
