[7905] = {id=7905,name="The Darkmoon Faire",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=5861,description="The Darkmoon Faire is coming! Experience our thrilling games, win fabulous prizes, have your fortune told! If you act right now, you can redeem this voucher for free prize tickets and a copy of the world-famous Darkmoon Adventurer's Guide to help you identify treasures in your travels! Just hand your voucher to Gelvas Grimegate located inside the Faire. Right now, the entrance to the Faire is outside Goldshire, in Elwynn Forest.",starts={{npcID=54334,x=0.622,y=0.73,zoneID=1519}},ends={{npcID=14828,x=0.48,y=0.648,zoneID=5861}},coords={x=0.622,y=0.73,source="quest_giver",zoneID=1519},questType="standard"},
[7907] = {id=7907,name="Darkmoon Beast Deck",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=5861,description="Now that you have gathered all of the Beast cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.",ends={{npcID=14847,x=0.518,y=0.606,zoneID=5861}},questType="standard"},
[7926] = {id=7926,name="The Darkmoon Faire",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=5861,description="The Darkmoon Faire is coming! Experience our thrilling games, win fabulous prizes, have your fortune told! If you act right now, you can redeem this voucher for free prize tickets and a copy of the world-famous Darkmoon Adventurer's Guide to help you identify treasures in your travels! Just hand your voucher to Gelvas Grimegate located inside the Faire. Right now, the entrance to the Faire is outside Thunder Bluff in Mulgore!",starts={{npcID=55382,x=0.48,y=0.62,zoneID=1637}},ends={{npcID=14828,x=0.48,y=0.648,zoneID=5861}},coords={x=0.48,y=0.62,source="quest_giver",zoneID=1637},questType="standard"},
