[7928] = {id=7928,name="Darkmoon Warlords Deck",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=5861,description="Now that you have gathered all of the Warlord cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded. You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.",ends={{npcID=14847,x=0.518,y=0.606,zoneID=5861}},questType="standard"},
[7929] = {id=7929,name="Darkmoon Elementals Deck",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=5861,description="Now that you have gathered all of the Elemental cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.",ends={{npcID=14847,x=0.518,y=0.606,zoneID=5861}},questType="standard"},
[7937] = {id=7937,name="Your Fortune Awaits You...",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=12,description="\"Your fortune awaits you in Eastvale.\" The fortune Sayge handed you feels slightly warm to the touch. Grasping it firmly, you see an image of the Eastvale Logging Camp in Elwynn Forest. Focusing closer in on the image, you see a haystack that sits next to a stable.",ends={{npcID=180025,x=0.847,y=0.644,zoneID=12}},questType="standard"},
[7945] = {id=7945,name="Your Fortune Awaits You...",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=215,description="\"Your fortune awaits you outside Palemane Rock.\" The fortune Sayge handed you feels slightly warm to the touch. Grasping it firmly, you see an image of the Palemane Rock of Mulgore. Focusing closer in on the image, you see a tree stump that sits close to the cave entrance.",ends={{npcID=180056,x=0.358,y=0.609,zoneID=215}},questType="standard"},
[7946] = {id=7946,name="Spawn of Jubjub",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=5861,starts={{npcID=14871,x=0.558,y=0.706,zoneID=5861}},ends={{npcID=14871,x=0.558,y=0.706,zoneID=5861}},coords={x=0.558,y=0.706,source="quest_giver",zoneID=5861},questType="standard"},
[8149] = {id=8149,name="Honoring a Hero",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1,description="During the Harvest Festival of Azeroth, we give thanks to heroes for the sacrifices - in some cases ultimate sacrifices - they have given on our behalf. The Alliance acknowledges many heroes, but none weave a more tragic tale than that of Uther Lightbringer. Help us honor Uther by taking this offering to his tomb in the Western Plaguelands. Place it at his statue, and then return to me. I'll only be here through the end of the festival, so waste no time in giving Uther his tribute.",starts={{npcID=15011,x=0.598,y=0.342,zoneID=1}},ends={{npcID=15011,x=0.598,y=0.342,zoneID=1}},coords={x=0.598,y=0.342,source="quest_giver",zoneID=1},questType="standard"},
[8150] = {id=8150,name="Honoring a Hero",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=331,description="During the Harvest Festival of Azeroth, we give thanks to heroes for the sacrifices - in some cases ultimate sacrifices - they have given on our behalf. The Horde acknowledges many heroes, but none exemplify strength and sacrifice more than Grom Hellscream. Help us honor Grom by taking this offering to his monument in the Demon Fall Canyon of Ashenvale. Place it at the base, and then return to me. I'll only be here through the end of the festival, so waste no time in giving Grom his tribute.",starts={{npcID=15012,x=0.462,y=0.15,zoneID=14}},ends={{npcID=15012,x=0.462,y=0.15,zoneID=14}},coords={x=0.462,y=0.15,source="quest_giver",zoneID=14},questType="standard"},
