[8272] = {id=8272,name="Hero of the Frostwolf",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=267,mapID=25,starts={{npcID=13817,x=0.586,y=0.342,mapID=25}},ends={{npcID=13817,x=0.586,y=0.342,mapID=25}},coords={x=0.586,y=0.342,source="quest_giver",mapID=25},questType="pvp"},
[8277] = {id=8277,name="Deadly Desert Venom",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1,description="Beetix Ficklespragg at your service! My cousin Noggle makes a living gathering rare herbs for Cenarion Hold alchemists. Or used to, anyway. He came back from his last trip with a strong poison running though his veins. I've managed to slow down the venom, but to fully neutralize it I need poison samples from whatever stung him. Noggle arrived from the north, so I'd bet my shirt stonelash scorpids or sand skitterers did it. Bring me some stingers and fangs and I'll try to make an antidote for him.",starts={{npcID=15189,x=0.554,y=0.362,zoneID=1377}},ends={{npcID=15189,x=0.554,y=0.362,zoneID=1377}},coords={x=0.554,y=0.362,source="quest_giver",zoneID=1377},questType="standard"},
[8278] = {id=8278,name="Noggle's Last Hope",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="Blasted! The antidote didn't work. Noggle must've been stung by one of the stronger creatures in the far south. I'm going to need you to go there and get me some more samples, . The good news is that since their poison is stronger I won't require as many. The bad news is that there are more kinds of poisonous creatures crawling around the southern area so you'll have to draw from more sources.",starts={{npcID=15189,x=0.554,y=0.362,zoneID=1377}},ends={{npcID=15189,x=0.554,y=0.362,zoneID=1377}},coords={x=0.554,y=0.362,source="quest_giver",zoneID=1377},questType="standard"},
[8279] = {id=8279,name="The Twilight Lexicon",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="The Twilight's Hammer are not kind to those that leave their ranks. They hunt me to this day like I'm some sort of beast! Needless to say, an enemy of theirs is a friend of mine! To decipher this Tablet I'll need the book used by their scribes to encode secret messages: the Twilight Lexicon. It's such an important tool that they keep its three chapters in different locations! The officers entrusted with the Lexicon are known as Twilight Keepers. Look for them at the Twilight's Hammer camps.",starts={{npcID=15194,x=0.686,y=0.63,zoneID=1377}},ends={{npcID=15194,x=0.686,y=0.63,zoneID=1377}},coords={x=0.686,y=0.63,source="quest_giver",zoneID=1377},questType="standard"},
[8280] = {id=8280,name="Securing the Supply Lines",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1,description="Cenarion Hold is a location of utmost strategic importance. I'm convinced that while we hold it our victory over the silithid is guaranteed. Provided our influx supplies can be maintained, that is. Desert worms have proven to be more of a threat to our supply caravans than even the silithid themselves. Just this morning, a large shipment of morrowgrain was ravaged by a group of dredge strikers . I need you to thin their numbers to ensure our supplies aren't jeopardized.",starts={{npcID=15191,x=0.548,y=0.358,zoneID=1377}},ends={{npcID=15191,x=0.548,y=0.358,zoneID=1377}},coords={x=0.548,y=0.358,source="quest_giver",zoneID=1377},questType="standard"},
[8281] = {id=8281,name="Stepping Up Security",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1,description="Your performance has been truly exemplary so far, . Our supply lines are not completely safe yet, however. In the absence of dredge strikers, their larger southern cousins will surely move in to take their place in the north. You'll have to kill quite a few dredge crushers to keep them at bay, but we cannot leave the safety of our supply lines to chance.",starts={{npcID=15191,x=0.548,y=0.358,zoneID=1377}},ends={{npcID=15191,x=0.548,y=0.358,zoneID=1377}},coords={x=0.548,y=0.358,source="quest_giver",zoneID=1377},questType="standard"},
[8282] = {id=8282,name="Noggle's Lost Satchel",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="Where am I? Where's my bag? *gasp* I must've lost it while fleeing from Deathclasp, the giant scorpid. In my rush to escape I walked right into a nest of stonelash flayers. The satchel I was carrying had all sorts of rare reagents in it. Without them, me and Beetix won't be able to make the potions that Cenarion Hold needs. I'm too weak to get up yet, but I can make it worth your while if you bring back my reagents. I ran into Deathclasp in the southern mountain range, behind Bronzebeard's camp.",starts={{npcID=15190,x=0.554,y=0.362,zoneID=1377}},ends={{npcID=15190,x=0.554,y=0.362,zoneID=1377}},coords={x=0.554,y=0.362,source="quest_giver",zoneID=1377},questType="standard"},
[8283] = {id=8283,name="Wanted - Deathclasp, Terror of the Sands",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="The terrible scorpid, Deathclasp, is believed to have retreated to the southern mountain range in the presence of increased silithid activity. She presents a great threat to patrols and expeditions in the southern regions. Individuals participating in her destruction will be remunerated handsomely. Inquire with Captain Vish Kozus , at the top of the Cenarion Hold Watchtower, regarding a reward.",starts={{npcID=180448,x=0.55,y=0.359,zoneID=1377}},ends={{npcID=15182,x=0.546,y=0.32,zoneID=1377}},coords={x=0.55,y=0.359,source="quest_giver",zoneID=1377},questType="standard"},
[8284] = {id=8284,name="The Twilight Mystery",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="A camp of Twilight's Hammer cultists once thrived northwest of here. If you were to venture there now, you'd find the area swarming with elementals and nothing but scattered pieces of wood and canvas to mark the spot where the camp was. I've recovered a few fragments of a clay tablet from the site, but I have too few of them to piece together anything useful. See if you can find the remaining tablet fragments so we can shed some light into the Twilight's Hammer presence here in Silithus .",starts={{npcID=15183,x=0.536,y=0.352,zoneID=1377}},ends={{npcID=15183,x=0.536,y=0.352,zoneID=1377}},coords={x=0.536,y=0.352,source="quest_giver",zoneID=1377},questType="standard"},
[8285] = {id=8285,name="The Deserter",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="There are rumors of a Twilight's Hammer member called Ortell having deserted his sect. Word has it he hid in the mountains south of Southwind Village, where he lives as a hermit. Perhaps you can enlist his help in deciphering the tablet. Take the restored tablet with you and seek out Ortell.",starts={{npcID=15183,x=0.536,y=0.352,zoneID=1377}},ends={{npcID=15194,x=0.686,y=0.63,zoneID=1377}},coords={x=0.536,y=0.352,source="quest_giver",zoneID=1377},questType="standard"},
[8287] = {id=8287,name="A Terrible Purpose",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="Ok, here we are... a pretty valuable chunk of information, I must say! I've seen the Cenarion Circle forces arrive at Silithus . They plan to drive the Twilight's Hammer out, don't they? This will help. Take this parchment to their leader, Commander Mar'alith . Soon the Twilight's Hammer will be vanquished and I will be outside their grasp for good!",starts={{npcID=15194,x=0.686,y=0.63,zoneID=1377}},ends={{npcID=15181,x=0.532,y=0.326,zoneID=1377}},coords={x=0.686,y=0.63,source="quest_giver",zoneID=1377},questType="standard"},
[8304] = {id=8304,name="Dearest Natalia",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="My dear Natalia has gone missing. Truth be told, she had been acting strangely for weeks leading up to her disappearance. I had caught her talking to herself when no one was around on more than one occasion. She was adamant that everything was ok and that she must be allowed to continue her research. She was last seen heading to Bronzebeard's camp to the south. My soldiers are spread too thin, . I need you to go to Bronzebeard's camp and question those dwarves.",starts={{npcID=15181,x=0.532,y=0.326,zoneID=1377}},ends={{npcID=15181,x=0.532,y=0.326,zoneID=1377}},coords={x=0.532,y=0.326,source="quest_giver",zoneID=1377},questType="standard"},
[8306] = {id=8306,name="Into The Maw of Madness",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="I need you to venture into Hive'Regal and find what became of my dearest Natalia, . This will be no easy task for you. Before you dive headlong into the maw of madness, make sure that you speak with those dwarves further. They might be able to give you some tips on dealing with the silithid that inhabit that hive. And , if she truly is as mad as they say... do what you must.",starts={{npcID=15181,x=0.532,y=0.326,zoneID=1377}},ends={{npcID=15181,x=0.532,y=0.326,zoneID=1377}},coords={x=0.532,y=0.326,source="quest_giver",zoneID=1377},questType="standard"},
[8307] = {id=8307,name="Desert Recipe",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="Adapting to life in the desert has been difficult to say the least. Not only do I miss the birds and trees of Auberdine but our food selection is severely limited by this arid environment. I'm trying to learn about desert herbs, but there aren't many. I've seen Twilight's Hammer groups from the camp west of here hunt sandworms for food. Sandworm meat is so bitter though, I can't imagine how they make it palatable. Keep your eyes open if you go to their camp and let me know if you learn anything.",starts={{npcID=15174,x=0.554,y=0.366,zoneID=1377}},ends={{npcID=180503,x=0.436,y=0.42,zoneID=1377}},coords={x=0.554,y=0.366,source="quest_giver",zoneID=1377},questType="standard"},
[8308] = {id=8308,name="Brann Bronzebeard's Lost Letter",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="To Whom It May Concern: If you're reading this, I'm either dead or soon to be dead. It's hard to say. Most of the crew is dead anyhow. Found information about a Titan. Great battle between him and an Old God. Yes, a bona fide Old God. Found ancient tunnel leading to Ahn'Qiraj. Taking it. Take this letter to my old camp. Make sure my monkey is getting adequate food, water, and hugs. -Brann Bronzebeard, Explorer Extreme P.S. Watch out for crazy Old God worshipping night elf.",ends={{npcID=15170,x=0.464,y=0.79,zoneID=1377}},questType="standard"},
[8309] = {id=8309,name="Glyph Chasing",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="After our initial foray into the hives and Mistress Mar'alith's subsequent madness the three hives have been spewing out bugs! The increased activity might be tied into the glyphs covering those strange crystals. If I can get rubbings of those crystals and the glyphs on them, we might be able to make sense of this madness. Take this transcription set and hit Hive'Regal to the east, . That's the last rubbing I need!",starts={{npcID=15170,x=0.464,y=0.79,zoneID=1377}},ends={{npcID=15170,x=0.464,y=0.79,zoneID=1377}},coords={x=0.464,y=0.79,source="quest_giver",zoneID=1377},questType="standard"},
[8310] = {id=8310,name="Breaking the Code",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="I think I can formulate an elixir that will allow us to more readily decipher the glyphs and language of the silithid and Qiraji! What do I need? Glad you asked! I need brains! Normally I'd need a brain from each silithid type that inhabit the hives. Another brave explorer brought me two of 'em here... and never came back from Hive'Regal. Bring me back a silithid brain from Hive'Regal... and be careful not to end up like him!",starts={{npcID=15171,x=0.46,y=0.792,zoneID=1377}},ends={{npcID=15171,x=0.46,y=0.792,zoneID=1377}},coords={x=0.46,y=0.792,source="quest_giver",zoneID=1377},questType="standard"},
[8311] = {id=8311,name="Hallow's End Treats for Jesper!",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,description="I'm not allowed to go trick-or-treating. After Deathwing's attack, I'm lucky Matron Nightingale lets me be this far away. If you trick-or-treat for me, I'd trade you the candy you get for some I already have! Each of the innkeepers in the big cities have candy they give for Hallow's End - talk to them and do the tricks they ask for! Also, a little gnome named Talvash in Ironforge is handing out candy as well. When you have all the candy, bring them back to me here!",starts={{npcID=15310,x=0.32,y=0.504,zoneID=12}},ends={{npcID=15310,x=0.32,y=0.504,zoneID=12}},coords={x=0.32,y=0.504,source="quest_giver",zoneID=12},questType="standard"},
[8312] = {id=8312,name="Hallow's End Treats for Spoops!",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1497,description="I want to keep trick-or-treating, but I can't because the Matron won't let me. If you go for me, I'd trade you the candy you get for some I already have! I think you'd like this candy - it makes you turn into things both funny and scary! Each of the innkeepers in the big cities have candy they give for Hallow's End - talk to them and do the tricks they ask for! Also, a troll named Kali Remik in Orgrimmar is handing out candy as well. When you have all the candy, bring them back to me here!",starts={{npcID=15309,x=0.62,y=0.664,zoneID=85},{npcID=15309,x=0.674,y=0.07,zoneID=1497}},ends={{npcID=15309,x=0.62,y=0.664,zoneID=85},{npcID=15309,x=0.674,y=0.07,zoneID=1497}},coords={x=0.62,y=0.664,source="quest_giver",zoneID=85},questType="standard"},
[8313] = {id=8313,name="Sharing the Knowledge",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="While the recipe for cooking sandworm meat is legible, it contains references to herbs and spices you've never heard of. Calandrath might have enough knowledge of the plants that grow in the desert to make sense of it.",starts={{npcID=180503,x=0.436,y=0.42,zoneID=1377}},ends={{npcID=15174,x=0.554,y=0.366,zoneID=1377}},coords={x=0.436,y=0.42,source="quest_giver",zoneID=1377},questType="standard"},
[8314] = {id=8314,name="Unraveling the Mystery",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="We're on the verge of a breakthrough, ! The rubbings you recovered have allowed us to recreate the glyphs on this crystalline prism. They are apparently a means for the Qiraji and other unknown entities to communicate various messages to the silithid. Unfortunately, that is all we could get out of the glyphs. We need to find a way to unlock the messages hidden within the crystals. Take the glyphed crystal prism to Geologist Larksbane at Cenarion Hold. She might be able to help.",starts={{npcID=15170,x=0.464,y=0.79,zoneID=1377}},ends={{npcID=15183,x=0.536,y=0.352,zoneID=1377}},coords={x=0.464,y=0.79,source="quest_giver",zoneID=1377},questType="standard"},
[8317] = {id=8317,name="Kitchen Assistance",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="That recipe sure will come in handy. I'd better get to work so I can have some smoked desert dumplings ready for today. I could use a hand in making some, I'll make it worth your while.",starts={{npcID=15174,x=0.554,y=0.366,zoneID=1377}},ends={{npcID=15174,x=0.554,y=0.366,zoneID=1377}},coords={x=0.554,y=0.366,source="quest_giver",zoneID=1377},questType="standard"},
[8318] = {id=8318,name="Secret Communication",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="Some of the Twilight's Hammer cultists carry around little papers with gibberish written on them. I want you to bring me a stack of them, . I can't figure out what the gibberish means, but that's not the point! These papers are how their different groups communicate secretly. The more texts we take out of circulation, the less they can communicate!",starts={{npcID=15306,x=0.532,y=0.35,zoneID=1377}},ends={{npcID=15306,x=0.532,y=0.35,zoneID=1377}},coords={x=0.532,y=0.35,source="quest_giver",zoneID=1377},questType="standard"},
[8319] = {id=8319,name="Encrypted Twilight Texts",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,starts={{npcID=15306,x=0.532,y=0.35,zoneID=1377}},ends={{npcID=15306,x=0.532,y=0.35,zoneID=1377}},coords={x=0.532,y=0.35,source="quest_giver",zoneID=1377},questType="standard"},
[8320] = {id=8320,name="Twilight Geolords",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="The Twilight's Hammer, an insane cult bent on destruction, set up camps in Silithus and perform rituals day and night. We do not yet know their plans, but we do think they are somehow linked to the pulsing red crystals spread across the desert. Although their mystery may one day be solved, we must first deal with their immediate threat. Go to their camps to the west and seek out Twilight geolords . They are the heads of these serpents; that is where we must strike!",starts={{npcID=15270,x=0.532,y=0.35,zoneID=1377}},ends={{npcID=15270,x=0.532,y=0.35,zoneID=1377}},coords={x=0.532,y=0.35,source="quest_giver",zoneID=1377},questType="standard"},
[8321] = {id=8321,name="Vyral the Vile",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="We have discovered another base of operations for the Twilight's Hammer. It is called Twilight's Run; it is a cave tucked in the northeast corner of Silithus . The local leader of the cult, Vyral the Vile, haunts that cave - it is he who you must next defeat. When you have done this, bring me his signet ring. Fortune to you, . The horrors of Twilight's Run are formidable indeed.",questType="standard"},
[8323] = {id=8323,name="True Believers",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,description="Now that I have the Twilight Lexicon in my possession, there is a small favor I'd like to ask of you. My former organization has a secret encoded bulletin they circulate on a monthly basis. If they make any progress searching for me or if they call off the search, word will be published on the True Believer. Although this information is obviously valuable to me, the publication contains other useful information that I can share. Bring me any encoded texts you find on Twilight's Hammer members.",starts={{npcID=15194,x=0.686,y=0.63,zoneID=1377}},ends={{npcID=15194,x=0.686,y=0.63,zoneID=1377}},coords={x=0.686,y=0.63,source="quest_giver",zoneID=1377},questType="standard"},
[8324] = {id=8324,name="Still Believing",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1377,starts={{npcID=15194,x=0.686,y=0.63,zoneID=1377}},ends={{npcID=15194,x=0.686,y=0.63,zoneID=1377}},coords={x=0.686,y=0.63,source="quest_giver",zoneID=1377},questType="standard"},
[8353] = {id=8353,name="Chicken Clucking for a Mint",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1537,description="Ah, trick-or-treating on behalf of a child, are we? I was going to say, you're a little old to be rummaging about for candies... Well, for my treat - an Ironforge Mint - you will need to... cluck like a chicken! Yes, chickens love mints... well OK, maybe they don't LOVE them... but I won't give you a mint unless you chicken cluck for me! Well , are you up to the challenge or not?! Time to earn your treat!",starts={{npcID=5111,x=0.186,y=0.514,zoneID=1537}},ends={{npcID=5111,x=0.186,y=0.514,zoneID=1537}},coords={x=0.186,y=0.514,source="quest_giver",zoneID=1537},questType="standard"},
[8354] = {id=8354,name="Chicken Clucking for a Mint",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1497,description="Ah, trick-or-treating on behalf of a child, are we? I was going to say, you're a little old to be rummaging about for candies... Well, for my treat - an Undercity Mint - you will need to... cluck like a chicken! Yes, chickens love mints... well OK, maybe they don't LOVE them... but I won't give you a mint unless you chicken cluck for me! Well , are you up to the challenge or not?! Time to earn your treat!",starts={{npcID=6741,x=0.676,y=0.382,zoneID=1497}},ends={{npcID=6741,x=0.676,y=0.382,zoneID=1497}},coords={x=0.676,y=0.382,source="quest_giver",zoneID=1497},questType="standard"},
[8355] = {id=8355,name="Incoming Gumdrop",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1537,description="A trick-or-treater! Huzzah! Well now, even though you're doing something noble and collecting candies for a child, I can't let you off the hook that easily. I have a yummy Gnomeregan Gumdrop to give to the sick child... if you make a train noise for me! Haha, yes, that'll be the trick! The price of this gumdrop is one train noise! Chugga-chugga, !",starts={{npcID=6826,x=0.36,y=0.04,zoneID=1537}},ends={{npcID=6826,x=0.36,y=0.04,zoneID=1537}},coords={x=0.36,y=0.04,source="quest_giver",zoneID=1537},questType="standard"},
[8356] = {id=8356,name="Flexing for Nougat",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1519,description="That's an... interesting costume you have on. Even though you're being nice and helping a child trick-or-treat this year, I'm afraid I'm going to have to ask you to perform a trick for me! Let's see... you look so strong and buff in that... costume... let's see you flex! Yes, go on now and flex for me, strong ! When and only when you flex, I'll give you some tasty Stormwind Nougat . It's a great Hallow's End treat.",starts={{npcID=6740,x=0.604,y=0.752,zoneID=1519}},ends={{npcID=6740,x=0.604,y=0.752,zoneID=1519}},coords={x=0.604,y=0.752,source="quest_giver",zoneID=1519},questType="standard"},
[8357] = {id=8357,name="Dancing for Marzipan",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1657,description="Even though you're trick-or-treating on behalf of a child, you still need to perform a trick for the treat! We can't very well change the tradition, now can we... I believe the cost of a piece of marzipan nowadays is to bust out and DANCE! That's right, let me see your moves! Dance for me, and I'll give you some tasty marzipan!",starts={{npcID=6735,x=0.624,y=0.328,zoneID=1657}},ends={{npcID=6735,x=0.624,y=0.328,zoneID=1657}},coords={x=0.624,y=0.328,source="quest_giver",zoneID=1657},questType="standard"},
[8358] = {id=8358,name="Incoming Gumdrop",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1637,description="A trick-or-treater! Yeah mon! Well now, even though you're doing something noble and collecting candies for a child, I can't let you off the hook that easily. I have a yummy Darkspear Gumdrop to give to the child... if you make a train noise for me! Haha, yes, that'll be the trick! The price of this gumdrop is one train noise! Chugga-chugga, !",starts={{npcID=11814,x=0.326,y=0.65,zoneID=1637}},ends={{npcID=11814,x=0.326,y=0.65,zoneID=1637}},coords={x=0.326,y=0.65,source="quest_giver",zoneID=1637},questType="standard"},
[8359] = {id=8359,name="Flexing for Nougat",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1637,description="That's an... interesting costume you have on. Even though you're being nice and helping a child trick-or-treat this year, I'm afraid I'm going to have to ask you to perform a trick for me! Let's see... you look so strong and buff in that... costume... let's see you flex! Yes, go on now and flex for me, strong ! When and only when you flex, I'll give you some tasty Orgrimmar Nougat . It's a great Hallow's End treat.",starts={{npcID=6929,x=0.534,y=0.788,zoneID=1637}},ends={{npcID=6929,x=0.534,y=0.788,zoneID=1637}},coords={x=0.534,y=0.788,source="quest_giver",zoneID=1637},questType="standard"},
[8360] = {id=8360,name="Dancing for Marzipan",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1638,description="Even though you're trick-or-treating on behalf of a child, you still need to perform a trick for the treat! We can't very well change the tradition, now can we... I believe the cost of a piece of marzipan nowadays is to bust out and DANCE! That's right, let me see your moves! Dance for me, and I'll give you some tasty marzipan!",starts={{npcID=6746,x=0.456,y=0.642,zoneID=1638}},ends={{npcID=6746,x=0.456,y=0.642,zoneID=1638}},coords={x=0.456,y=0.642,source="quest_giver",zoneID=1638},questType="standard"},
[8446] = {id=8446,name="Shrouded in Nightmare",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=493,description="Corruption seeps from this object. There may be a link between this object and the dragons coming forth from the Dream. You must find someone that can decipher the meaning of this item. Perhaps the druids of the Moonglade or Cenarion Hold could assist you further.",ends={{npcID=11832,x=0.362,y=0.418,zoneID=493}},questType="standard"},
[8447] = {id=8447,name="Waking Legends",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=493,description="The waters of Lake Elune'ara should dissolve the nightmares engulfing this object. Give me a moment to perform the cleansing, .",starts={{npcID=11832,x=0.362,y=0.418,zoneID=493}},ends={{npcID=11832,x=0.362,y=0.418,zoneID=493}},coords={x=0.362,y=0.418,source="quest_giver",zoneID=493},questType="standard"},
[8470] = {id=8470,name="Deadwood Ritual Totem",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=361,description="You have found one of the Deadwood furbolg's ritual totems. The totem itself is of non-descript construction, but a palpable sense of despair emanates from it. If there were any object that might best exemplify the corruption that the Deadwood furbolg suffer under, this item would clearly be it. One of the furbolgs inside Timbermaw Hold may have a use for such an item... that is, if you've earned their trust enough for them to speak with you.",ends={{npcID=11558,x=0.646,y=0.054,zoneID=361}},questType="standard"},
[8481] = {id=8481,name="The Root of All Evil",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=361,description=", thanks to you we have devised a way to summon forth the root of all evil for the Winterfall tribe - the corrupting demon that dominates them! Take this torch to the mouth of Grolnar's personal cave and plant it there. Doing so will force the demon to reveal itself and investigate. This is when you and your allies must strike it down! Only the essence of the fallen demon will begin the lengthy healing process of the Winterfall tribe... and the salvation of Timbermaw Hold .",starts={{npcID=11555,x=0.644,y=0.05,zoneID=361}},ends={{npcID=11555,x=0.644,y=0.05,zoneID=361}},coords={x=0.644,y=0.05,source="quest_giver",zoneID=361},questType="group"},
[8544] = {id=8544,name="Conqueror's Spaulders",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=5892,description="It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon. Bring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!",starts={{npcID=15502,x=0.506,y=0.826,zoneID=5892}},ends={{npcID=15502,x=0.506,y=0.826,zoneID=5892}},coords={x=0.506,y=0.826,source="quest_giver",zoneID=5892},questType="raid"},
[8556] = {id=8556,name="Signet of Unyielding Strength",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=5695,description="The rings worn by the Qiraji lieutenants are rumored to grant them formidable abilities. The corrupted gems that adorn them could, in theory, be swapped out with more pure materials to create uncorrupted versions of the rings. The gems that adorn Qiraji idols would work quite well, as their quality is superior. Bring me the ring and idols and I'll create a powerful ring for you, .",starts={{npcID=15498,x=0.594,y=0.14,zoneID=5695}},ends={{npcID=15498,x=0.594,y=0.14,zoneID=5695}},coords={x=0.594,y=0.14,source="quest_giver",zoneID=5695},questType="raid"},
[8557] = {id=8557,name="Drape of Unyielding Strength",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=5695,description="I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, . I can make you a protective item that'll be of assistance in the fight against our enemy, . I shall need a Qiraji drape, which I'll resize for you of course. I'll also need idols and scarabs which I'll use to create a suitable clasp. I promise you won't be disappointed.",starts={{npcID=15500,x=0.594,y=0.14,zoneID=5695}},ends={{npcID=15500,x=0.594,y=0.14,zoneID=5695}},coords={x=0.594,y=0.14,source="quest_giver",zoneID=5695},questType="raid"},
[8558] = {id=8558,name="Sickle of Unyielding Strength",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=5695,description="The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong. Just the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces. Prove your allegiance to the Circle, , and I will make you a powerful weapon from the finest Qiraji materials.",starts={{npcID=15499,x=0.594,y=0.14,zoneID=5695}},ends={{npcID=15499,x=0.594,y=0.14,zoneID=5695}},coords={x=0.594,y=0.14,source="quest_giver",zoneID=5695},questType="raid"},
[8559] = {id=8559,name="Conqueror's Greaves",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=3428,description="Qiraji magic is strong and ancient. The most powerful qiraji wield items of such might, they'd give pause even to a dragon. Bring me the qiraji bindings of command and other minor components by and I'll create a set of powerful boots for you. You will find them useful in the fight against the enemy.",questType="raid"},
[8560] = {id=8560,name="Conqueror's Legguards",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=3428,description="You seek to prove your worth to my kind, mortal? Very well, perhaps we can be of mutual assistance. The ancient sandworm, Ouro, is a being of legendary power. He is rumored to have been created by the Old God himself as a mockery of life. His skin is unnatural... thick, nearly impregnable, yet it's flexible and allows him to move with the speed and grace of a much smaller creature. Bring me a sample of his skin along with other minor components and I shall craft you leggings of great power.",questType="raid"},
[8561] = {id=8561,name="Conqueror's Crown",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=5892,description="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos. In my visions I see their monstrous faces adorned by powerful crowns. But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs. Bring me the components I require, . I will give you a headpiece of unmatched power.",starts={{npcID=15502,x=0.506,y=0.826,zoneID=5892}},ends={{npcID=15502,x=0.506,y=0.826,zoneID=5892}},coords={x=0.506,y=0.826,source="quest_giver",zoneID=5892},questType="raid"},
[8562] = {id=8562,name="Conqueror's Breastplate",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=3428,description="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power. When the stars are favorable, he will lash out against all living beings with terrible wrath. You must find him before then and find a way to bring his existence to an end. Do this and bring me a piece of his husk. I shall grant you armor no mortal has ever worn... armor fit for one who has slain a god!",questType="raid"},
[8579] = {id=8579,name="Mortal Champions",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=3428,questType="raid"},
