[8655] = {id=8655,name="Avenger's Greaves",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=3428,description="Qiraji magic is strong and ancient. The most powerful qiraji wield items of such might, they'd give pause even to a dragon. Bring me the qiraji bindings of dominance and other minor components and I'll create a set of powerful boots for you. You will find them useful in the fight against the enemy.",questType="raid"},
[8656] = {id=8656,name="Striker's Hauberk",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=3428,description="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power. When the stars are favorable, he will lash out against all living beings with terrible wrath. You must find him before then and find a way to bring his existence to an end. Do this and bring me a piece of his husk. I shall grant you armor no mortal has ever worn... armor fit for one who has slain a god!",questType="raid"},
[8657] = {id=8657,name="Striker's Diadem",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=5892,description="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos. In my visions I see their monstrous faces adorned by powerful crowns. But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs. Bring me the components I require, . I will make you a headpiece of unmatched power.",starts={{npcID=15502,x=0.506,y=0.826,zoneID=5892}},ends={{npcID=15502,x=0.506,y=0.826,zoneID=5892}},coords={x=0.506,y=0.826,source="quest_giver",zoneID=5892},questType="raid"},
[8658] = {id=8658,name="Striker's Leggings",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=3428,description="You seek to prove your worth to my kind, mortal? Very well, perhaps we can be of mutual assistance. The ancient sandworm, Ouro, is a being of legendary power. He is rumored to have been created by the Old God himself as a mockery of life. His skin is unnatural... thick, nearly impregnable, yet it's flexible and allows him to move with the speed and grace of a much smaller creature. Bring me a sample of his skin along with other minor components and I shall craft you leggings of great power.",questType="raid"},
[8659] = {id=8659,name="Striker's Pauldrons",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=5892,description="It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon. Bring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!",starts={{npcID=15502,x=0.506,y=0.826,zoneID=5892}},ends={{npcID=15502,x=0.506,y=0.826,zoneID=5892}},coords={x=0.506,y=0.826,source="quest_giver",zoneID=5892},questType="raid"},
