[8697] = {id=8697,name="Ring of Infinite Wisdom",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=5695,description="The rings worn by the Qiraji lieutenants are rumored to grant them formidable abilities. The corrupted gems that adorn them could, in theory, be swapped out with more pure materials to create uncorrupted versions of the rings. The gems that adorn Qiraji idols would work quite well, as their quality is superior. Bring me the ring and idols and I'll create a powerful ring for you, .",starts={{npcID=15498,x=0.594,y=0.14,zoneID=5695}},ends={{npcID=15498,x=0.594,y=0.14,zoneID=5695}},coords={x=0.594,y=0.14,source="quest_giver",zoneID=5695},questType="raid"},
