[8784] = {id=8784,name="Secrets of the Qiraji",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=5892,description="You have discovered an ancient Qiraji artifact ! Perhaps one of the dragons near the entrance of the temple would have a use for this relic.",ends={{npcID=15502,x=0.506,y=0.826,zoneID=5892}},questType="standard"},
[8788] = {id=8788,name="A Gently Shaken Gift",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=1637,mapID=85,starts={{npcID=180746,x=0.334,y=0.659,mapID=87},{npcID=180746,x=0.491,y=0.782,mapID=85}},ends={{npcID=180746,x=0.334,y=0.659,mapID=87},{npcID=180746,x=0.491,y=0.782,mapID=85}},coords={x=0.334,y=0.659,source="quest_giver",mapID=85},questType="standard"},
[8789] = {id=8789,name="Imperial Qiraji Armaments",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=3428,description="We have not sat idly by for a millennium, . We have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world. And we have learned of their own internal treachery. Weaknesses exist and we know how to use those weaknesses to our advantage. Find and bring me their ceremonial armaments: Combined with the element created from the volatility of their own God, they will become a force of reckoning.",questType="raid"},
[8790] = {id=8790,name="Imperial Qiraji Regalia",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=3428,description="Arygos theorizes that the element which is born of conflicts between the Old Gods and their minions is also extremely deadly to them under the right conditions. I speak of Elementium, mortal. Find and bring me Imperial Qiraji Regalia and the toxic element and I shall infuse weapons of great power.",questType="raid"},
[8791] = {id=8791,name="The Fall of Ossirian",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=3429,description="A terrible menace has been laid to rest. The cruel Ossirian has been vanquished. The denizens of Kalimdor would be relieved to know of this victory. Take Ossirian's head and present it to Commander Mar'alith of Cenarion Hold.",ends={{npcID=15181,x=0.532,y=0.326,zoneID=1377}},questType="raid"},
[8801] = {id=8801,name="C'Thun's Legacy",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=3428,mapID=327,description="The walls of Ahn'Qiraj tremble. A force of evil, older than the world itself, has been destroyed. As you look at the remnants of the colossal abomination your heart nearly freezes. Even in death you can feel the legacy of C'Thun's evil around you. You have done what was thought to be impossible. You grab at an eye stalk of the fiend, stowing it safely in your pack. Take the Eye of C'Thun to the dragons in the next chamber.",questType="standard"},
[8802] = {id=8802,name="The Savior of Kalimdor",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=440,description="To the Caverns of Time you go, . Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection.",questType="standard"},
[8803] = {id=8803,name="A Festive Gift",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=1637,mapID=85,starts={{npcID=180793,x=0.336,y=0.66,mapID=87},{npcID=180793,x=0.496,y=0.777,mapID=85}},ends={{npcID=180793,x=0.336,y=0.66,mapID=87},{npcID=180793,x=0.496,y=0.777,mapID=85}},coords={x=0.336,y=0.66,source="quest_giver",mapID=85},questType="standard"},
[8827] = {id=8827,name="Winter's Presents",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1537,description="I hear Greatfather Winter - with the generous support of Smokywood Pastures - has put presents for everyone under the tree in Ironforge. I wish I could go, but I've got to look after the PX-238 Winter Wondervolt. But you should definitely check it out. I'm sure Greatfather Winter has some presents with your name on them.",ends={{npcID=13444,x=0.332,y=0.658,zoneID=1537}},questType="standard"},
[8828] = {id=8828,name="Winter's Presents",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1637,description="I hear Great-father Winter - with the generous support of Smokywood Pastures - has put presents for everyone under the tree in Orgrimmar. I wish I could go, but I've got to look after the PX-238 Winter Wondervolt. But you should definitely check it out. I'm sure Great-father Winter has some presents with your name on them.",ends={{npcID=13445,x=0.498,y=0.78,zoneID=1637}},questType="standard"},
[8860] = {id=8860,name="New Year Celebrations!",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1519,description="Stormwind is holding a celebration for the new year! All day long today you can get free booze, and at night they'll put on a firework show! It should be pretty nice... but Booty Bay is also having a party today; I bet it'll be even better! Well anyway, Innkeeper Allison in Stormwind needs a supply of Smokywood Pastures fare to help feed all the party goers. Can you do me a favor and deliver it? Thanks, ! Innkeeper Allison is in The Gilded Rose, in the Trade District of Stormwind.",ends={{npcID=6740,x=0.604,y=0.752,zoneID=1519}},questType="standard"},
[8861] = {id=8861,name="New Year Celebrations!",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1638,description="Thunder Bluff is holding a celebration for the new year! All day you'll find free booze there, and at night they'll put on a firework show! It should be pretty nice... but Booty Bay is also having a party today; I bet it'll be even better! Well anyway, Innkeeper Pala in Thunder Bluff needs a supply of Smokywood Pastures fare to help feed all the party goers. Can you do me a favor and deliver it? Thanks, ! Innkeeper Pala is in the inn near the bridge to Hunter's Rise.",ends={{npcID=6746,x=0.456,y=0.642,zoneID=1638}},questType="standard"},
[8866] = {id=8866,name="Bronzebeard the Elder",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=1537,mapID=87,starts={{npcID=15871,x=0.294,y=0.172,mapID=87}},ends={{npcID=15871,x=0.294,y=0.172,mapID=87}},coords={x=0.294,y=0.172,source="quest_giver",mapID=87},questType="standard"},
[8867] = {id=8867,name="Lunar Fireworks",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=6611,description="Every year the druids of Moonglade hold a celebration of our city's great triumph over an ancient evil. We celebrate the wisdom of our elders, share in magnificent feasts and of course... shoot fireworks! For a small donation you can purchase colorful rockets from our vendor. Try using some of the launchers around here, .",starts={{npcID=15895,x=0.342,y=0.506,zoneID=12},{npcID=15895,x=0.658,y=0.36,zoneID=1497},{npcID=15895,x=0.29,y=0.16,zoneID=1537},{npcID=15895,x=0.49,y=0.558,zoneID=1637},{npcID=15895,x=0.71,y=0.282,zoneID=1638},{npcID=15895,x=0.386,y=0.304,zoneID=1657},{npcID=15895,x=0.728,y=0.826,zoneID=3487},{npcID=15895,x=0.742,y=0.572,zoneID=3557},{npcID=15895,x=0.534,y=0.33,zoneID=3703},{npcID=15895,x=0.852,y=0.648,zoneID=5840}},ends={{npcID=15895,x=0.342,y=0.506,zoneID=12},{npcID=15895,x=0.658,y=0.36,zoneID=1497},{npcID=15895,x=0.29,y=0.16,zoneID=1537},{npcID=15895,x=0.49,y=0.558,zoneID=1637},{npcID=15895,x=0.71,y=0.282,zoneID=1638},{npcID=15895,x=0.386,y=0.304,zoneID=1657},{npcID=15895,x=0.728,y=0.826,zoneID=3487},{npcID=15895,x=0.742,y=0.572,zoneID=3557},{npcID=15895,x=0.534,y=0.33,zoneID=3703},{npcID=15895,x=0.852,y=0.648,zoneID=5840}},coords={x=0.342,y=0.506,source="quest_giver",zoneID=12},questType="standard"},
[8868] = {id=8868,name="Elune's Blessing",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=493,description="The beast Omen was once a hero of this world. A wolf of great strength and fortune, Omen fought beside the heroes of the War of the Ancients until he succumbed to demonic magics. Turning against his allies, he raged across Azeroth and carried death and terror in his wake. Finally defeated here, in Moonglade, Omen now sleeps among the silt of Lake Elune'ara. But each new year, during the festival, he stirs... Gather cohorts, , and summon and defeat the beast Omen. Earn the blessing of Elune!",starts={{npcID=15864,x=0.54,y=0.35,zoneID=493}},ends={{npcID=15864,x=0.54,y=0.35,zoneID=493}},coords={x=0.54,y=0.35,source="quest_giver",zoneID=493},questType="raid"},
[8870] = {id=8870,name="The Lunar Festival",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=6611,description="It's that time of the year, ! The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival. ou will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.",starts={{npcID=15892,x=0.346,y=0.506,zoneID=12},{npcID=15892,x=0.618,y=0.756,zoneID=1519},{npcID=15892,x=0.308,y=0.618,zoneID=1537},{npcID=15892,x=0.45,y=0.52,zoneID=1657},{npcID=15892,x=0.852,y=0.644,zoneID=5840}},ends={{npcID=15895,x=0.342,y=0.506,zoneID=12},{npcID=15895,x=0.29,y=0.16,zoneID=1537},{npcID=15895,x=0.386,y=0.304,zoneID=1657},{npcID=15895,x=0.852,y=0.648,zoneID=5840},{npcID=15895,x=0.658,y=0.36,zoneID=1497},{npcID=15895,x=0.49,y=0.558,zoneID=1637},{npcID=15895,x=0.71,y=0.282,zoneID=1638},{npcID=15895,x=0.728,y=0.826,zoneID=3487},{npcID=15895,x=0.742,y=0.572,zoneID=3557},{npcID=15895,x=0.534,y=0.33,zoneID=3703}},coords={x=0.346,y=0.506,source="quest_giver",zoneID=12},questType="standard"},
