[8883] = {id=8883,name="Valadar Starsong",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=493,description="Now that you have your Lunar Festival invitation, you may travel to Moonglade! There you will find many revelers, and in the village of Nighthaven Valadar Starsong and his sister Fariel await those eager to participate in the celebration. Travel to Moonglade through the greater moonlight and speak with Valadar Starsong ; see what prizes you might gain during the festival!",starts={{npcID=15895,x=0.342,y=0.506,zoneID=12},{npcID=15895,x=0.658,y=0.36,zoneID=1497},{npcID=15895,x=0.29,y=0.16,zoneID=1537},{npcID=15895,x=0.49,y=0.558,zoneID=1637},{npcID=15895,x=0.71,y=0.282,zoneID=1638},{npcID=15895,x=0.386,y=0.304,zoneID=1657},{npcID=15895,x=0.728,y=0.826,zoneID=3487},{npcID=15895,x=0.742,y=0.572,zoneID=3557},{npcID=15895,x=0.534,y=0.33,zoneID=3703},{npcID=15895,x=0.852,y=0.648,zoneID=5840}},ends={{npcID=15864,x=0.54,y=0.35,zoneID=493}},coords={x=0.342,y=0.506,source="quest_giver",zoneID=12},questType="standard"},
[9250] = {id=9250,name="Frame of Atiesh",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=440,mapID=71,description="With the frame formed, Atiesh is nearly whole. Only the head and base of the staff are now missing. There is also a minor issue regarding the staff being a conduit for Sargeras's evil. Find someone that can assist you in locating the remaining pieces and exorcising the evil from the staff.",questType="raid"},
[9251] = {id=9251,name="Atiesh, the Befouled Greatstaff",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=440,description="You question why you are still alive. After all, you have in your possession an item of great evil. The answer is not clear, . I only do as I must. Kel'Thuzad sits atop his throne in Naxxramas, plotting... He seeks that which you hold and holds that which you seek. As for the base of the staff; the dwarf, Brann Bronzebeard, held it when he entered Ahn'Qiraj. He has left Ahn'Qiraj but the base of Atiesh remains. Should you succeed in recovering the pieces, return them to me.",questType="raid"},
[9259] = {id=9259,name="Traitor to the Bloodsail",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=5287,starts={{npcID=16399,x=0.484,y=0.632,zoneID=5287}},ends={{npcID=16399,x=0.484,y=0.632,zoneID=5287}},coords={x=0.484,y=0.632,source="quest_giver",zoneID=5287},questType="standard"},
[9267] = {id=9267,name="Mending Old Wounds",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=10413,questType="standard"},
[9268] = {id=9268,name="War at Sea",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=440,starts={{npcID=16417,x=0.504,y=0.272,zoneID=440}},ends={{npcID=16417,x=0.504,y=0.272,zoneID=440}},coords={x=0.504,y=0.272,source="quest_giver",zoneID=440},questType="standard"},
[9272] = {id=9272,name="Dressing the Part",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=5287,mapID=210,starts={{npcID=2546,x=0.466,y=0.952,mapID=210}},ends={{npcID=2546,x=0.466,y=0.952,mapID=210}},coords={x=0.466,y=0.952,source="quest_giver",mapID=210},questType="standard"},
[9364] = {id=9364,name="Fragmented Magic",level=30,requiredLevel=30,faction="none",expansion=0,description="My research has revealed a unique purpose for the prismatic shell . Carry the shell and cast your polymorph spell on the Spitelash in Azshara. If you wait a few moments, the chaotic aura of the shell will cause them to split into several smaller clones for a few moments. Kill these clones as quickly as possible, and the shell will collect their essence. When the shell is full, return it to me.",questType="standard"},
[9415] = {id=9415,name="Report to Marshal Bluewall",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=1377,description="Are you Marshal Bluewall 's new recruits? Of course you are. What are you waiting for? Good soldiers are dying in the desert. Aren't you excited to join them? Now, get going and don't dry out on the way.",starts={{npcID=17082,x=0.544,y=0.328,zoneID=1377}},ends={{npcID=17080,x=0.396,y=0.468,zoneID=1377}},coords={x=0.544,y=0.328,source="quest_giver",zoneID=1377},questType="standard"},
[9416] = {id=9416,name="Report to General Kirika",level=15,requiredLevel=15,faction="horde",expansion=0,zoneID=1377,description="You must be one of General Kirika 's new recruits. It's about time you showed up. Bodies wear down quick in the desert. The dwarves have been getting reinforcements daily, and we can't afford to lose ground in our struggle for resources in Silithus . Get your instructions from the General. It's not my job to train you, just find you.",starts={{npcID=17081,x=0.53,y=0.346,zoneID=1377}},ends={{npcID=17079,x=0.546,y=0.628,zoneID=1377}},coords={x=0.53,y=0.346,source="quest_giver",zoneID=1377},questType="standard"},
}
end)
